function editCustomModal(){if(!isStaff()||S.portalMode||!S.ticket.can_work)throw new Error('Edycja jest dostępna tylko w panelu zespołu.');showModal(`<h2>Dane formularza · ${e(S.ticket.key)}</h2><form data-form="custom-values">${S.ticket.request_form.fields.map(f=>customControl(f,S.ticket.custom_values[f.key])).join('')}${saveFooter()}</form>`);}
function workflowStatusRow(s={key:freshKey('status'),name:'',category:'in_progress'}){
  return `<tr class="workflow-status-row" data-state-key="${e(s.key)}"><td><span class="status-drag-handle" draggable="true" role="button" tabindex="0" aria-label="Przeciągnij status; do klawiatury użyj przycisków strzałek" title="Przeciągnij, aby zmienić kolejność">⠿ Przeciągnij</span>${input('Nazwa statusu','state_name',s.name,'required maxlength="80"')}</td><td><label>Kategoria<select name="state_category">${options(S.meta.statuses,s.category)}</select></label></td><td><div class="button-row"><button type="button" data-v7-action="state-up" aria-label="Przesuń status wyżej">↑</button><button type="button" data-v7-action="state-down" aria-label="Przesuń status niżej">↓</button><button type="button" data-action="remove-state">Usuń</button></div></td></tr>`;
}
function readWorkflowStatuses(){if(document.querySelector('[data-form=workflow][data-central]'))return S.projectWorkflow.statuses;return [...document.querySelectorAll('.workflow-status-row')].map(row=>({key:row.dataset.stateKey,name:$('[name="state_name"]',row).value,category:$('[name="state_category"]',row).value}));}
function workflowStateMap(){return Object.fromEntries(readWorkflowStatuses().map(s=>[s.key,s.name||'Nowy status']));}
function transitionRow(t={},map=workflowStateMap()){
  return `<tr class="transition-row"><td><label>Ze statusu<select name="transition_from" data-state-select required>${options(map,t.from)}</select></label></td><td><label>Do statusu<select name="transition_to" data-state-select required>${options(map,t.to)}</select></label></td><td><label>Kto może wykonać<select name="transition_actor">${options({team:'Zespół',customer:'Zgłaszający',both:'Zespół i zgłaszający'},t.actor||'team')}</select></label></td><td>${input('Nazwa przycisku','transition_name',t.name,'maxlength="100" placeholder="Domyślnie nazwa statusu"')}</td><td><button type="button" data-action="remove-transition">Usuń</button></td></tr>`;
}
function ruleRow(r={},map=workflowStateMap()){
  const legacy=!r.actions&&r.to,actions=r.actions||(legacy?[{type:'status',value:r.to}]:[{type:'comment',body:'',internal:false}]),event=r.event||'status_changed';
  return `<fieldset class="rule-row" data-rule-id="${e(r.id||crypto.randomUUID())}" data-legacy="${Boolean(r.legacy||legacy)}"><legend>Reguła automatyzacji</legend><div class="field-editor-heading">${check('Reguła aktywna','rule_enabled',r.enabled??true)}<div class="button-row"><button type="button" data-action="rule-up" aria-label="Przesuń regułę wyżej">↑</button><button type="button" data-action="rule-down" aria-label="Przesuń regułę niżej">↓</button><button type="button" data-action="remove-rule">Usuń regułę</button></div></div>${input('Nazwa reguły','rule_name',r.name,'required minlength="2" maxlength="120"')}<div class="automation-step"><h3>1. Gdy</h3><div class="form-row"><label>Wyzwalacz<select name="rule_event">${options(S.meta.workflow_events,event)}</select></label><label>Status w chwili zdarzenia<select name="rule_from" data-state-select data-state-any required>${options({'*':'Dowolny status',...map},r.from||'*')}</select></label></div><div class="rule-delay form-row" ${['status_elapsed','silence_elapsed'].includes(event)?'':'hidden'}>${input('Po upływie','rule_delay',r.after?.value||5,'type="number" min="1" max="525600"')}<label>Jednostka<select name="rule_unit">${options({minutes:'Minuty',hours:'Godziny',days:'Dni (24 godziny)'},r.after?.unit||'days')}</select></label></div></div><div class="automation-step"><div class="section-heading"><h3>2. Jeśli</h3><button type="button" data-action="add-condition">Dodaj warunek</button></div><label>Warunki<select name="rule_match">${options({all:'Wszystkie muszą być spełnione (ORAZ)',any:'Wystarczy jeden (LUB)'},r.match||'all')}</select></label><div class="rule-conditions">${(r.conditions||[]).map(c=>conditionRow(c,map)).join('')}</div><p class="hint">Bez warunków reguła działa dla każdego zgłoszenia pasującego do wyzwalacza i statusu.</p></div><div class="automation-step"><div class="section-heading"><h3>3. Wykonaj</h3><button type="button" data-action="add-rule-action">Dodaj akcję</button></div><div class="rule-actions">${actions.map(a=>automationActionRow(a,map)).join('')}</div></div></fieldset>`;
}
const conditionFields={author_kind:'Autor komentarza',comment_visibility:'Widoczność komentarza',comment_body:'Treść komentarza',title:'Tytuł zgłoszenia',origin:'Źródło zdarzenia',reporter_id:'ID zgłaszającego',organization_id:'ID organizacji',status_category:'Kategoria statusu',previous_status:'Poprzedni status',priority:'Priorytet',type:'Klasyfikacja',assignee_id:'Opiekun',request_type_id:'Formularz',customer_reply_locked:'Blokada odpowiedzi klienta'};
const automationActionNames={email:'Wyślij e-mail z szablonu',webhook:'Wyślij webhook',resolution:'Ustaw rozwiązanie',comment:'Dodaj komentarz bota',status:'Zmień status',priority:'Zmień priorytet',assign:'Przypisz opiekuna',lock:'Zablokuj odpowiedzi i otwieranie przez klienta',unlock:'Odblokuj odpowiedzi klienta'};
function conditionValue(field,value,map){
  if(['comment_body','title','origin','reporter_id','organization_id'].includes(field))return input('Wartość','condition_value',value,'maxlength="1000"');
  if(field==='author_kind')return pick('Autor','condition_value',{customer:'Klient',agent:'Agent / administrator',service:'Konto automatyzacji'},value);
  if(field==='comment_visibility')return pick('Widoczność','condition_value',{public:'Publiczny',internal:'Notatka wewnętrzna'},value);
  const agents={'':'Nieprzypisane',...Object.fromEntries((S.automationAgents||[]).map(u=>[u.id,u.name]))};
  const values={...{status_category:S.meta.statuses,previous_status:map,priority:S.meta.priorities,type:S.meta.types,assignee_id:agents,request_type_id:Object.fromEntries((S.automationForms||[]).map(f=>[f.id,f.name])),customer_reply_locked:{true:'Tak',false:'Nie'}}[field]};
  if(value!==null&&value!==undefined&&!Object.hasOwn(values,String(value)))values[String(value)]='Niedostępna wartość ('+value+')';
  return `<label>Wartość<select name="condition_value" ${field==='previous_status'?'data-state-select':''}>${options(values,value===null?'':String(value??''))}</select></label>`;
}
function conditionRow(c={},map=workflowStateMap()){
  const field=c.field||'priority';
  return `<div class="automation-condition"><label>Pole<select name="condition_field">${options(conditionFields,field)}</select></label><label>Porównanie<select name="condition_op">${options({eq:'Jest równe',neq:'Jest różne',contains:'Zawiera (tekst)',not_contains:'Nie zawiera (tekst)'},c.op||'eq')}</select></label><div class="condition-value">${conditionValue(field,c.value,map)}</div><button type="button" data-action="remove-condition" aria-label="Usuń warunek">×</button></div>`;
}
function automationActionValue(a,map){
  if(a.type==='email')return pick('Szablon e-mail','action_value',Object.fromEntries((S.automationMailTemplates||[]).filter(t=>t.enabled).map(t=>[t.id,t.name])),a.value);
  if(a.type==='webhook')return pick('Webhook wychodzący','action_value',Object.fromEntries((S.automationWebhooks||[]).filter(w=>w.direction==='outbound'&&w.enabled).map(w=>[w.id,w.name])),a.value);
  if(a.type==='resolution')return '<label>Rozwiązanie<textarea name="action_body" rows="4" required>'+e(a.body||'')+'</textarea></label>';
  if(a.type==='comment')return `${pick('Konto automatyzacji autora','action_bot',Object.fromEntries((S.automationAuthors||S.automationAgents||[]).map(u=>[u.id,u.name])),a.bot_id,'Domyślny bot automatyzacji')}<label>Treść wiadomości<textarea name="action_body" rows="4" required maxlength="10000" placeholder="Dzień dobry, sprawa {{ticket.key}} została rozwiązana…">${e(a.body||'')}</textarea></label>${check('Notatka wewnętrzna — tylko dla zespołu','action_internal',a.internal??false)}<p class="hint">Znaczniki: <code>{{ticket.key}}</code>, <code>{{ticket.title}}</code>, <code>{{ticket.status}}</code>, <code>{{project.name}}</code>, <code>{{reporter.name}}</code>, <code>{{assignee.name}}</code>.</p>`;
  if(a.type==='status')return `<label>Status docelowy<select name="action_value" data-state-select required>${options(map,a.value)}</select></label><label>Rozwiązanie (jeśli wymagane)<textarea name="action_resolution" rows="2">${e(a.resolution||'')}</textarea></label>`;
  if(a.type==='priority')return `<label>Priorytet<select name="action_value">${options(S.meta.priorities,a.value||'P3')}</select></label>`;
  if(a.type==='assign'){const agents={actor:'Osoba wywołująca zdarzenie',reporter:'Zgłaszający (musi być agentem)',bot:'Domyślny bot',...Object.fromEntries((S.automationAgents||[]).map(u=>[u.id,u.name]))};if(a.value&&!Object.hasOwn(agents,String(a.value)))agents[a.value]='Niedostępny opiekun ('+a.value+')';return `<label>Opiekun<select name="action_value">${options(agents,a.value,'Nieprzypisane')}</select></label>`;}
  return `<p class="hint">${a.type==='lock'?'Klient nie będzie mógł komentować, edytować danych ani samodzielnie ponownie otworzyć zgłoszenia. Zespół zachowa możliwość obsługi.':'Klient odzyska możliwość odpowiedzi, jeśli zgłoszenie ma aktywny status. Samo odblokowanie nie otwiera zamkniętej sprawy.'}</p>`;
}
function automationActionRow(a={type:'comment'},map=workflowStateMap()){
  return `<div class="automation-action"><div class="section-heading"><label>Akcja<select name="action_type">${options(automationActionNames,a.type)}</select></label><div class="button-row"><button type="button" data-action="action-up" aria-label="Przesuń akcję wyżej">↑</button><button type="button" data-action="action-down" aria-label="Przesuń akcję niżej">↓</button><button type="button" data-action="remove-rule-action">Usuń</button></div></div><div class="action-value">${automationActionValue(a,map)}</div></div>`;
}
function readAutomationRules(){return [...document.querySelectorAll('.rule-row')].map(row=>{
  const value=name=>$(`[name="${name}"]`,row).value,event=value('rule_event');
  return {id:row.dataset.ruleId,name:value('rule_name'),enabled:$('[name="rule_enabled"]',row).checked,event,from:value('rule_from'),match:value('rule_match'),
    ...(row.dataset.legacy==='true'?{legacy:true}:{}),...(['status_elapsed','silence_elapsed'].includes(event)?{after:{value:Number(value('rule_delay')),unit:value('rule_unit')}}:{}),
    conditions:[...row.querySelectorAll('.automation-condition')].map(el=>{const field=$('[name="condition_field"]',el).value,raw=$('[name="condition_value"]',el).value;return {field,op:$('[name="condition_op"]',el).value,value:field==='customer_reply_locked'?raw==='true':['assignee_id','request_type_id','reporter_id','organization_id'].includes(field)?raw===''?null:Number(raw):raw};}),
    actions:[...row.querySelectorAll('.automation-action')].map(el=>{const type=$('[name="action_type"]',el).value;
      if(type==='comment')return {type,body:$('[name="action_body"]',el).value,internal:$('[name="action_internal"]',el).checked,bot_id:Number($('[name="action_bot"]',el)?.value)||null};
      if(type==='resolution')return {type,body:$('[name="action_body"]',el).value};
      if(['webhook','email'].includes(type))return {type,value:Number($('[name="action_value"]',el).value)};
      if(['status','priority','assign'].includes(type)){const value=$('[name="action_value"]',el).value;return {type,value:type==='assign'?value===''?null:['actor','reporter','bot'].includes(value)?value:Number(value):value,...(type==='status'?{resolution:$('[name="action_resolution"]',el)?.value||''}:{})};}return {type};})};
});}
function automationHistory(data){
  const names={done:'Wykonano',failed:'Błąd',skipped:'Pominięto',queued:'Zaplanowano'};
  return `<details class="automation-history"><summary>Harmonogram i ostatnie wykonania</summary><p class="hint">Do 50 nadchodzących lub błędnych zadań i 50 ostatnich wykonań. <button type="button" data-action="refresh-automation">Odśwież historię</button></p><h3>Zaplanowane zadania</h3><div class="table-scroll"><table><thead><tr><th>Sprawa</th><th>Reguła</th><th>Termin</th><th>Stan</th></tr></thead><tbody>${(data.jobs||[]).map(j=>`<tr><td><a href="#/ticket/${e(j.ticket_key)}">${e(j.ticket_key)}</a></td><td>${e(j.rule_name)}${j.last_error?`<small class="row-meta">${e(j.last_error)}</small>`:''}</td><td>${date(new Date(j.due_at).toISOString())}</td><td>${e(names[j.status])}${j.status==='failed'?` <button type="button" data-action="retry-automation" data-id="${j.id}">Ponów</button>`:''}</td></tr>`).join('')||'<tr><td colspan="4">Brak oczekujących zadań.</td></tr>'}</tbody></table></div><h3>Historia automatyzacji</h3><div class="table-scroll"><table><thead><tr><th>Czas</th><th>Sprawa / reguła</th><th>Wynik</th></tr></thead><tbody>${(data.runs||[]).map(r=>`<tr><td>${date(r.created_at)}</td><td><a href="#/ticket/${e(r.ticket_key)}">${e(r.ticket_key)}</a> · ${e(r.rule_name)}<small class="row-meta">${e(S.meta.workflow_events[r.event]||r.event)}</small></td><td>${e(names[r.status])}<small class="row-meta">${e(r.detail)}</small></td></tr>`).join('')||'<tr><td colspan="3">Reguły nie zostały jeszcze wykonane.</td></tr>'}</tbody></table></div></details>`;
}
function readWorkflow(){
  if($('[data-form="workflow"][data-central]'))return {...S.projectWorkflow,rules:readAutomationRules()};
  const form=$('[data-form="workflow"], [data-v6="template"]');
  return {version:Number(form.dataset.version),initial:form.elements.initial.value,statuses:readWorkflowStatuses(),transitions:[...form.querySelectorAll('.transition-row')].map(row=>({from:$('[name="transition_from"]',row).value,to:$('[name="transition_to"]',row).value,actor:$('[name="transition_actor"]',row).value,name:$('[name="transition_name"]',row).value})),rules:readAutomationRules()};
}
function workflowGraphLegacy(w,focus){
  const selected=w.statuses.find(s=>s.key===focus)||w.statuses.find(s=>s.key===w.initial)||w.statuses[0];
  return `<div class="workflow-lanes">${Object.entries(S.meta.statuses).map(([category,name])=>`<div class="workflow-lane"><h3>${e(name)}</h3>${w.statuses.filter(s=>s.category===category).map(s=>`<button type="button" class="workflow-node ${e(category)}${selected?.key===s.key?' focused':''}" data-action="focus-state" data-state="${e(s.key)}">${e(s.name||'Nowy status')}${w.initial===s.key?'<small>Początek</small>':''}<small>${w.transitions.filter(t=>t.from===s.key).length} przejść</small></button>`).join('')||'<span class="hint">—</span>'}</div>`).join('')}</div>${selected?`<div class="workflow-focus"><strong>${e(selected.name||'Nowy status')}</strong><span aria-hidden="true">→</span><div>${w.transitions.filter(t=>t.from===selected.key).map(t=>`<span class="transition-chip">${e(w.statuses.find(s=>s.key===t.to)?.name||'Usunięty status')}<small>${{team:'Zespół',customer:'Zgłaszający',both:'Zespół i zgłaszający'}[t.actor]}</small></span>`).join('')||'<span class="hint">Brak przejść wychodzących</span>'}</div></div>`:''}`;
}
function updateWorkflowPreview(sync=false){
  if(!$('[data-form="workflow"], [data-v6="template"]'))return;
  if(sync){const map=workflowStateMap();document.querySelectorAll('[data-state-select]').forEach(el=>{const v=el.value,values=el.hasAttribute('data-state-any')?{'*':'Dowolny status',...map}:map;el.innerHTML=options(values,v);if(!Object.hasOwn(values,v))el.value='';});}
  const host=$('#workflow-graph');host.innerHTML=workflowGraph(readWorkflow(),host.dataset.focus);
}
async function legacyWorkflowEditor(p){
  const [w,agents,forms,history,hooks]=await Promise.all([api('/projects/'+p.id+'/workflow'),api('/projects/'+p.id+'/agents'),api('/projects/'+p.id+'/request-types?surface=manage'),api('/projects/'+p.id+'/automation'),api('/desk/webhooks')]);
  S.automationWebhooks=Array.isArray(hooks)?hooks.filter(h=>h.project_id===p.id):[];S.automationAgents=Array.isArray(agents)?agents:[];S.automationForms=Array.isArray(forms)?forms:[];const map=Object.fromEntries(w.statuses.map(s=>[s.key,s.name]));
  return `<form data-form="workflow" data-central="true" data-version="${w.version}"><section class="panel detail-panel"><div class="section-heading"><div><h2>Mapa statusów</h2><p class="hint">Statusy, ich kolejność i przejścia edytuj w Ustawieniach → Szablony statusów. Tutaj ustawiasz reguły automatyzacji projektu.</p>${p.workflow_template_id?`<a href="#/admin/templates/${p.workflow_template_id}">Edytuj przypisany szablon →</a>`:''}</div><a class="button" href="#/board?project=${p.id}">Otwórz tablicę</a></div><div id="workflow-graph">${workflowGraph(w,w.initial)}</div></section><section class="panel detail-panel"><div class="section-heading"><h2>3. Automatyzacja</h2><button type="button" data-action="add-rule">Dodaj regułę</button></div><p class="hint">Reguły działają kolejno od góry. Każda może mieć warunki ORAZ/LUB i wiele akcji. Zmiana statusu przez bota może uruchomić następne reguły; każda reguła wykona się najwyżej raz w jednym łańcuchu zdarzeń.</p><div id="workflow-rules">${w.rules.map(r=>ruleRow(r,map)).join('')}</div><p class="hint">Harmonogram działa po restarcie. Dni liczone są jako 24 godziny. Nowa lub zmieniona reguła czasowa daje istniejącym zgłoszeniom pełny okres od jej zapisu; dla kolejnych zgłoszeń czas biegnie od wejścia w wybrany status. Zmiana nazwy statusu bez edycji reguły nie przesuwa terminów. Komentarze bota nie uruchamiają wyzwalaczy odpowiedzi.</p><div id="automation-history">${automationHistory(history)}</div></section><div class="editor-save">${saveFooter('Zapisz reguły')}</div></form>`;
}

document.addEventListener('click',async event=>{
  const b=event.target.closest('[data-action]');if(!b||b.disabled)return;
  try{
    switch(b.dataset.action){
      case 'refresh': if(S.user){S.meta=await api('/meta');await route();}else await boot();break;
      case 'close-modal':modal.close();break;
      case 'logout':await api('/logout',{method:'POST',data:{}});S.user=null;S.csrf='';S.meta=null;modal.close();location.hash='#/login';loginView();break;
      case 'password':showModal(S.user.auth_source==='ldap'?'<h2>Konto firmowe LDAP</h2><p>Hasło zmienisz w katalogu firmowym. W razie problemu skontaktuj się z administratorem systemu.</p>':passwordForm());break;
      case 'create':await createTicketModal(b.dataset.project,b.dataset.type,b.dataset.portal==='true'||S.portalMode);break;
      case 'assign-me':b.disabled=true;await changeTicket({assignee_id:S.user.id});break;
      case 'reopen':b.disabled=true;await changeTicket({status:'open'});break;
      case 'close-ticket':b.disabled=true;await changeTicket({status:'closed'});break;
      case 'edit-ticket':if(!isStaff()||S.portalMode||!S.ticket.can_work)throw new Error('Edycja jest dostępna tylko w panelu zespołu.');showModal(`<h2>Edytuj ${e(S.ticket.key)}</h2><form data-form="edit-ticket">${input('Temat','title',S.ticket.title,'required minlength="3" maxlength="200"')}<label>Opis<textarea name="description" required rows="10" minlength="3" maxlength="20000">${e(S.ticket.description)}</textarea></label>${saveFooter()}</form>`);break;
      case 'create-project':location.href='/#/projects/new';break;
      case 'clone-form':{b.disabled=true;const copied=await api('/projects/'+S.project.id+'/request-types/'+b.dataset.id+'/clone',{method:'POST',data:{}});await refreshMeta();location.hash='#/project/'+S.project.id+'/request-type/'+copied.id;break;}
      case 'add-field':if(document.querySelectorAll('.field-editor').length>=30)throw new Error('Maksymalnie 30 pól.');$('#field-editors').insertAdjacentHTML('beforeend',fieldEditorRow());updateFormPreview();break;
      case 'remove-field':b.closest('.field-editor').remove();updateFormPreview();break;
      case 'field-up':case 'field-down':{const row=b.closest('.field-editor'),next=b.dataset.action==='field-up'?row.previousElementSibling:row.nextElementSibling;if(next){if(b.dataset.action==='field-up')row.parentElement.insertBefore(row,next);else row.parentElement.insertBefore(next,row);}updateFormPreview();break;}
      case 'edit-custom':editCustomModal();break;
      case 'transition-ticket':await transitionWithResolution(b.dataset.state);break;
      case 'add-state':if(!$('[data-v6="template"]'))throw new Error('Statusy edytuj w szablonach.');if(readWorkflowStatuses().length>=30)throw new Error('Maksymalnie 30 statusów.');$('#workflow-statuses').insertAdjacentHTML('beforeend',workflowStatusRow());updateWorkflowPreview(true);break;
      case 'remove-state':{const row=b.closest('.workflow-status-row'),key=row.dataset.stateKey,w=readWorkflow();if(w.initial===key||w.transitions.some(t=>t.from===key||t.to===key)||w.rules.some(r=>r.from===key||r.actions.some(a=>a.type==='status'&&a.value===key)||r.conditions.some(c=>c.field==='previous_status'&&c.value===key)))throw new Error('Najpierw usuń przejścia i reguły odwołujące się do tego statusu oraz zmień status początkowy.');row.remove();updateWorkflowPreview(true);break;}
      case 'add-transition':$('#workflow-transitions').insertAdjacentHTML('beforeend',transitionRow());updateWorkflowPreview();break;
      case 'remove-transition':b.closest('.transition-row').remove();updateWorkflowPreview();break;
      case 'add-rule':$('#workflow-rules').insertAdjacentHTML('beforeend',ruleRow());break;
      case 'remove-rule':b.closest('.rule-row').remove();break;
      case 'rule-up':{const row=b.closest('.rule-row');if(row.previousElementSibling)row.parentNode.insertBefore(row,row.previousElementSibling);break;}
      case 'rule-down':{const row=b.closest('.rule-row');if(row.nextElementSibling)row.parentNode.insertBefore(row.nextElementSibling,row);break;}
      case 'add-condition':$('.rule-conditions',b.closest('.rule-row')).insertAdjacentHTML('beforeend',conditionRow());break;
      case 'remove-condition':b.closest('.automation-condition').remove();break;
      case 'add-rule-action':$('.rule-actions',b.closest('.rule-row')).insertAdjacentHTML('beforeend',automationActionRow());break;
      case 'remove-rule-action':b.closest('.automation-action').remove();break;
      case 'action-up':{const row=b.closest('.automation-action');if(row.previousElementSibling)row.parentNode.insertBefore(row,row.previousElementSibling);break;}
      case 'action-down':{const row=b.closest('.automation-action');if(row.nextElementSibling)row.parentNode.insertBefore(row.nextElementSibling,row);break;}
      case 'retry-automation':await api('/projects/'+S.project.id+'/automation/'+b.dataset.id+'/retry',{method:'POST',data:{}});notify('Sprawdzono zadanie ponownie.');$('#automation-history').innerHTML=automationHistory(await api('/projects/'+S.project.id+'/automation'));$('.automation-history').open=true;break;
      case 'refresh-automation':$('#automation-history').innerHTML=automationHistory(await api('/projects/'+S.project.id+'/automation'));$('.automation-history').open=true;break;
      case 'focus-state':$('#workflow-graph').dataset.focus=b.dataset.state;updateWorkflowPreview();break;
      case 'create-user':showModal(`<h2>Dodaj użytkownika</h2><form data-form="create-user">${input('Imię','first_name','','required maxlength="60"')}${input('Nazwisko','last_name','','maxlength="80"')}${input('Nazwa użytkownika (opcjonalna)','username','','maxlength="80" placeholder="Puste = wygeneruj automatycznie"')}${input('E-mail','email','','type="email" required maxlength="254" autocomplete="off"')}<label>Rola globalna<select name="role" data-user-role>${options(roles,'customer')}</select></label>${check('Konto firmowe','is_internal',false)}${input('Hasło (opcjonalne)','password','','type="password" minlength="12" maxlength="256" autocomplete="new-password"')}<p class="hint">Podane hasło działa bez wymuszonej zmiany. Puste hasło wysyła zaproszenie e-mail. Obsługę projektów przypisz po utworzeniu konta.</p>${saveFooter('Dodaj użytkownika')}</form>`);break;
      case 'edit-user':editUserModal(S.users.find(u=>u.id===Number(b.dataset.id)));break;
      case 'approve-user':{const u=S.users.find(u=>u.id===Number(b.dataset.id));showModal(`<h2>Zatwierdź konto klienta</h2><p><strong>${e(u.name)}</strong><br>${e(u.email)}</p><p>Konto będzie mogło się zalogować i korzystać z portali dla wszystkich zalogowanych. Dostęp do pozostałych portali nadajesz w projektach.</p><form data-form="approve-user" data-id="${u.id}" data-version="${u.version}">${saveFooter('Zatwierdź konto')}</form>`);break;}
      case 'add-member':b.disabled=true;await memberModal();b.disabled=false;break;
      case 'remove-member':{const id=Number(b.dataset.id);showModal(`<h2>Usuń ręczne członkostwo</h2><p>Ta osoba straci ręcznie nadaną rolę w projekcie. Uprawnienia pochodzące z LDAP i ustawienia dostępu do portalu pozostaną aktywne.</p><form data-form="remove-member" data-id="${id}">${saveFooter('Usuń członkostwo')}</form>`);break;}
      case 'add-mapping':$('#mappings').insertAdjacentHTML('beforeend',mappingRow());$('[data-form="ldap"]').dataset.dirty='true';break;
      case 'remove-mapping':b.closest('.mapping-row').remove();$('[data-form="ldap"]').dataset.dirty='true';break;
      case 'ldap-preview':{
        if($('[data-form="ldap"]').dataset.dirty==='true')throw new Error('Najpierw zapisz zmienioną konfigurację LDAP.');
        b.disabled=true;b.textContent='Pobieranie katalogu…';const preview=await api('/ldap/preview',{method:'POST',data:{}});S.preview=preview;const host=$('#ldap-preview');if(host)host.innerHTML=previewHtml(preview);b.disabled=false;b.textContent='Odśwież podgląd';break;
      }
      case 'test-email':b.disabled=true;await api('/test-email',{method:'POST',data:{}});notify('Wiadomość dodana do kolejki. Odśwież za chwilę, aby sprawdzić wysyłkę.');b.disabled=false;break;
    }
  }catch(err){b.disabled=false;if(b.dataset.action==='ldap-preview')b.textContent='Sprawdź i pokaż zmiany';notify(err.message,true);}
});
function projectPayload(fields){return {...fields,next_number:Number(fields.next_number),number_padding:Number(fields.number_padding),archived:fields.archived==='on'};}
async function refreshMeta(){S.meta=await api('/meta');}
function authResult(message){authCard('Sprawdź dalsze instrukcje',`<p class="result-message">${e(message)}</p><a class="button primary full" href="#/login">Przejdź do logowania</a>`);}
document.addEventListener('submit',async event=>{
  const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();if(form.dataset.busy)return;
  const fields=Object.fromEntries(new FormData(form)),error=$('.form-error',form),buttons=[...form.querySelectorAll('button[type="submit"]')];
  form.dataset.busy='1';buttons.forEach(b=>b.disabled=true);if(error)error.textContent='';
  try{
    switch(form.dataset.form){
      case 'login':{const result=await api('/login',{method:'POST',data:fields});if(result.mfa_required){S.mfaChallenge=result.challenge;mfaLoginView();return;}S.user=result.user;S.csrf=result.csrf;if(!S.user.must_change)await refreshMeta();await route();break;}
      case 'register':if(fields.password!==fields.repeat)throw new Error('Hasła muszą być takie same.');authResult((await api('/register',{method:'POST',data:{first_name:fields.first_name,last_name:fields.last_name,email:fields.email,password:fields.password}})).message);break;
      case 'forgot':case 'resend':authResult((await api(form.dataset.form==='forgot'?'/forgot-password':'/resend-verification',{method:'POST',data:{email:fields.email}})).message);break;
      case 'verify':authResult((await api('/verify-email',{method:'POST',data:{token:form.dataset.token}})).message);break;
      case 'reset':if(fields.password!==fields.repeat)throw new Error('Hasła muszą być takie same.');authResult((await api('/reset-password',{method:'POST',data:{token:form.dataset.token,password:fields.password}})).message);S.user=null;S.csrf='';break;
      case 'password':if(fields.new_password!==fields.repeat)throw new Error('Nowe hasła muszą być takie same.');await api('/password',{method:'POST',data:fields});S.user.must_change=false;modal.close();await refreshMeta();notify('Hasło zostało zmienione.');await route();break;
      case 'filters':{const params=new URLSearchParams(Object.entries(fields).filter(([,v])=>v));if(S.portalMode)params.set('own','1');const hash='#/'+form.dataset.view+'?'+params;if(location.hash===hash)await route();else location.hash=hash;break;}
      case 'create-ticket':{const definition=form._catalog?.find(f=>f.id===Number(fields.request_type_id));if(!definition)throw new Error('Wybierz dostępny formularz.');const result=await api('/tickets',{method:'POST',data:{title:fields.title,description:fields.description,priority:fields.priority||definition.default_priority,project_id:Number(fields.project_id),request_type_id:definition.id,request_type_version:definition.version,custom_values:customValues(form,definition.fields),...(form.dataset.surface==='team'?{reporter_id:Number(fields.reporter_id),}:{}),organization_id:fields.organization_id?Number(fields.organization_id):null,asset_id:form._assetId??null,from_portal:form.dataset.portal==='true'}});modal.close();notify('Utworzono '+result.key);await refreshMeta();location.hash='#/ticket/'+result.key;break;}
      case 'ticket-fields':await changeTicket({...fields,assignee_id:fields.assignee_id?Number(fields.assignee_id):null});break;
      case 'edit-ticket':await changeTicket(fields);modal.close();break;
      case 'comment':await api('/tickets/'+S.ticket.key+'/comments',{method:'POST',data:{body:fields.body,internal:fields.internal==='on'}});notify('Dodano wiadomość.');await route();break;
      case 'create-project':{const result=await api('/projects',{method:'POST',data:projectPayload(fields)});modal.close();await refreshMeta();notify('Utworzono projekt.');location.href=result.project_type==='assets'?'/#/admin/assets?project='+result.id:'/#/project/'+result.id;break;}
      case 'request-type':{
        const data={name:fields.name,description:fields.description,group_name:fields.group_name,icon:fields.icon,base_type:fields.base_type,default_priority:fields.default_priority,sort_order:Number(fields.sort_order),enabled:fields.enabled==='on',portal_visible:fields.portal_visible==='on',portal_priority:fields.portal_priority==='on',fields:readFieldEditors(),base_fields:{title:{hidden:fields.hide_title==='on',value:fields.fixed_title||''},description:{hidden:fields.hide_description==='on',value:fields.fixed_description||''}},version:Number(form.dataset.version)};
        const result=await api('/projects/'+S.project.id+'/request-types'+(form.dataset.id?'/'+form.dataset.id:''),{method:form.dataset.id?'PATCH':'POST',data});await refreshMeta();notify('Zapisano formularz.');if(form.dataset.id)await route();else location.hash='#/project/'+S.project.id+'/request-type/'+result.id;break;
      }
      case 'custom-values':await changeTicket({custom_values:customValues(form,S.ticket.request_form.fields)});modal.close();break;
      case 'workflow':await api('/projects/'+S.project.id+'/workflow',{method:'PATCH',data:readWorkflow()});await refreshMeta();notify('Zapisano mapę statusów i reguły.');await route();break;
      case 'project-general':await api('/projects/'+S.project.id,{method:'PATCH',data:{...projectPayload(fields),version:Number(form.dataset.version)}});await refreshMeta();notify('Zapisano projekt.');await route();break;
      case 'project-portal':await api('/projects/'+S.project.id,{method:'PATCH',data:{portal_slug:fields.portal_slug,portal_title:fields.portal_title,portal_description:fields.portal_description,version:Number(form.dataset.version)}});await refreshMeta();notify('Zapisano portal.');await route();break;
      case 'project-sla':{const policy=Object.fromEntries(Object.keys(S.meta.priorities).map(k=>[k,[Number(fields[k+'_response']),Number(fields[k+'_resolution'])]]));await api('/projects/'+S.project.id,{method:'PATCH',data:{sla_policy:policy,version:Number(form.dataset.version)}});await refreshMeta();notify('Zapisano terminy.');await route();break;}
      case 'member-search':{const list=await api('/projects/'+S.project.id+'/candidates?q='+encodeURIComponent(fields.q));$('#member-candidates').innerHTML=options(Object.fromEntries(list.map(u=>[u.id,u.name+' · '+u.email+' · '+roles[u.role]])),null);break;}
      case 'member':case 'remove-member':await api('/projects/'+S.project.id+'/members',{method:'POST',data:{user_id:Number(form.dataset.form==='member'?fields.user_id:form.dataset.id),role:form.dataset.form==='member'?fields.role:null}});modal.close();await refreshMeta();notify('Zapisano uprawnienia.');await route();break;
      case 'create-user':await api('/users',{method:'POST',data:{...fields,...(!fields.username?{username:undefined}:{}),is_internal:fields.is_internal==='on'}});modal.close();await refreshMeta();notify('Dodano użytkownika.');await route();break;
      case 'edit-user':{const data={version:Number(form.dataset.version),active:fields.active==='on'};if(form.dataset.source==='local'){data.first_name=fields.first_name;data.last_name=fields.last_name;data.email=fields.email;data.role=fields.role;data.is_internal=fields.is_internal==='on';if(fields.new_password)data.new_password=fields.new_password;}await api('/users/'+form.dataset.id,{method:'PATCH',data});modal.close();notify('Zapisano dostęp.');await refreshMeta();await route();break;}
      case 'approve-user':await api('/users/'+form.dataset.id,{method:'PATCH',data:{version:Number(form.dataset.version),approve:true}});modal.close();notify('Konto zatwierdzone.');await route();break;
      case 'settings':await api('/settings',{method:'PATCH',data:{...fields,version:Number(form.dataset.version),allowed_domains:fields.allowed_domains.split(/[\s,;]+/).filter(Boolean)}});S.config=await api('/public-config');await refreshMeta();notify('Zapisano ustawienia.');await route();break;
      case 'ldap':{
        const config={...S.ldap.config};for(const k of ['url','bind_dn','base_dn','user_filter','ca_pem','uid_attribute','login_attribute','email_attribute','name_attribute','group_attribute','default_role'])config[k]=fields[k];
        for(const k of ['enabled','is_internal','disable_missing'])config[k]=fields[k]==='on';for(const k of ['interval_minutes','max_disable_percent'])config[k]=Number(fields[k]);
        config.global_admin_group_dns=(fields.global_admin_group_dns||'').split(/\r?\n/).map(v=>v.trim()).filter(Boolean);
        config.global_admin_users=(fields.global_admin_users||'').split(/\r?\n/).map(v=>v.trim()).filter(Boolean);
        config.mappings=[...form.querySelectorAll('.mapping-row')].map(row=>({group_dn:$('[name="group_dn"]',row).value,project_id:Number($('[name="project_id"]',row).value),role:$('[name="mapping_role"]',row).value}));
        await api('/ldap',{method:'PATCH',data:{config,version:Number(form.dataset.version),bind_password:fields.bind_password}});notify('Zapisano LDAP. Pobierz podgląd zmian.');await route();break;
      }
      case 'ldap-apply':await api('/ldap/apply',{method:'POST',data:{preview_id:S.preview.preview_id,confirm_deactivation:fields.confirm_deactivation==='on'}});await refreshMeta();notify('Synchronizacja zakończona.');await route();break;
    }
  }catch(err){if(error&&form.isConnected)error.textContent=err.message;else notify(err.message,true);}
  finally{delete form.dataset.busy;buttons.forEach(b=>b.disabled=false);}
});
document.addEventListener('change',async event=>{
  if(event.target.matches('[name="rule_event"]'))$('.rule-delay',event.target.closest('.rule-row')).hidden=!['status_elapsed','silence_elapsed'].includes(event.target.value);
  if(event.target.matches('[name="condition_field"]'))$('.condition-value',event.target.closest('.automation-condition')).innerHTML=conditionValue(event.target.value,undefined,workflowStateMap());
  if(event.target.matches('[name="action_type"]'))$('.action-value',event.target.closest('.automation-action')).innerHTML=automationActionValue({type:event.target.value},workflowStateMap());
  if(event.target.closest('[data-form="ldap"]'))event.target.closest('form').dataset.dirty='true';
  if(event.target.matches('[data-ticket-project]'))return updateTicketTypes();
  if(event.target.matches('[data-ticket-form]'))return renderRequestFields(event.target.form);
  if(event.target.matches('[data-filter-project]')){const target=$('[data-filter-state]',event.target.form);target.innerHTML=options(statusFilterMap(event.target.value),'','Wszystkie statusy');return;}
  if(event.target.matches('[data-workspace-project]')){location.hash='#/queue'+(event.target.value?'?project='+event.target.value:'');return;}
  if(event.target.matches('[data-field-type]')){const row=event.target.closest('.field-editor'),type=event.target.value;$('.field-options',row).hidden=!['select','multiselect'].includes(type);$('.field-number',row).hidden=type!=='number';$('.field-length',row).hidden=!['text','textarea'].includes(type);}
  if(event.target.closest('[data-form="request-type"]'))updateFormPreview();
  if(event.target.closest('[data-form="workflow"]'))updateWorkflowPreview(event.target.closest('.workflow-status-row')!==null);

  if(event.target.matches('[data-user-role]'))event.target.form.elements.is_internal.checked=event.target.value!=='customer';
  const control=event.target.closest('[data-ticket-status]');if(!control)return;control.disabled=true;
  try{await boardTransition(control.dataset.ticketStatus,control.value,Number(control.dataset.version));control.disabled=false;}catch(err){notify(err.message,true);await route();}
});
let dragging=null;
document.addEventListener('dragstart',event => { if(event.target.closest('.workflow-status-row'))return;const card=event.target.closest('.kanban-card'); if(!card || card.draggable!==true || event.target.closest('select,button,input')) return event.preventDefault(); dragging={key:card.dataset.key,version:Number(card.dataset.version),workflow_version:Number(card.dataset.workflowVersion),transitions:JSON.parse(card.dataset.transitions)}; event.dataTransfer.setData('text/plain',card.dataset.key); event.dataTransfer.effectAllowed='move'; });
document.addEventListener('dragover',event=>{ const column=event.target.closest('.kanban-column'); if(column && dragging) {event.preventDefault();event.dataTransfer.dropEffect='move';} });
document.addEventListener('dragend',()=>{dragging=null;});
document.addEventListener('drop',async event=>{const column=event.target.closest('.kanban-column');if(!column||!dragging)return;event.preventDefault();const ticket=dragging;dragging=null;try{if(!column.dataset.project||!ticket.transitions.includes(column.dataset.status))throw new Error('Mapa statusów nie pozwala na to przejście.');await boardTransition(ticket.key,column.dataset.status,ticket.version);}catch(err){notify(err.message,true);await route();}});
document.addEventListener('input',event=>{if(event.target.closest('[data-form="request-type"]')&&!event.target.closest('#form-preview-fields'))updateFormPreview();if(event.target.matches('[name="state_name"]'))updateWorkflowPreview(true);});
window.addEventListener('hashchange',()=>{modal.close();void route();});
// Administration and ticket tools, v0.5.
const extraNames={sync:'Synchronizacja projektów',mail:'Poczta zespołów · IMAP i SMTP',sso:'Logowanie SSO',webhooks:'Webhooki',organizations:'Firmy i grupy klientów',templates:'Szablony statusów',assets:'Środki trwałe',approvals:'Zmiany profili',events:'Błędy modułów'};
const multi=(label,name,map,values=[])=>`<label>${e(label)}<select name="${e(name)}" multiple size="${Math.min(6,Math.max(3,Object.keys(map).length))}">${Object.entries(map).map(([k,v])=>`<option value="${e(k)}"${values.map(String).includes(String(k))?' selected':''}>${e(v)}</option>`).join('')}</select><small>Możesz zaznaczyć kilka pozycji.</small></label>`;
const pick=(label,name,map,value,emptyLabel)=>`<label>${e(label)}<select name="${e(name)}">${options(map,value,emptyLabel)}</select></label>`;
const duration=ms=>{const m=Math.floor(Math.max(0,Number(ms)||0)/60000),d=Math.floor(m/1440),h=Math.floor(m%1440/60);return `${d?d+' d ':''}${h?h+' godz. ':''}${m%60} min`;};
const selected=(f,n)=>[...(f.elements[n]?.selectedOptions||[])].map(o=>o.value);
const extraButton=(action,label,attrs='')=>`<button type="button" data-extra-action="${action}" ${attrs}>${e(label)}</button>`;
function applyTheme(value=S.user?.theme||'system'){if(!document.documentElement)return;const dark=value==='dark'||value==='system'&&window.matchMedia?.('(prefers-color-scheme: dark)').matches;document.documentElement.dataset.theme=dark?'dark':'light';}
function transitionButtons(t){if(!t.can_work||t.archived_at||t.status==='closed'||t.project_archived||!t.transitions.length)return '';const button=x=>`<button class="${x===t.transitions[0]?'primary':''}" data-action="transition-ticket" data-state="${e(x.to)}">${e(x.name)}</button>`;return `<div class="transition-bar" aria-label="Dozwolone przejścia">${t.transitions.slice(0,2).map(button).join('')}${t.transitions[2]?`<div class="split-transition">${button(t.transitions[2])}${t.transitions.length>3?`<details class="transition-menu"><summary aria-label="Pozostałe przejścia">▾</summary><div>${t.transitions.slice(3).map(button).join('')}</div></details>`:''}</div>`:''}</div>`;}
function commentMarkup(c){const refs=new Map((c.links||[]).map(l=>[l.text,l.key])),mentions=new Map((c.mentions||[]).map(m=>[m.username,m]));return String(c.body||'').split(/(\b[A-Z][A-Z0-9]{1,9}-\d{1,10}\b|@[a-zA-Z0-9._-]+)/g).map(part=>refs.has(part)?`<a href="#/ticket/${e(refs.get(part))}">${e(part)}</a>`:part.startsWith('@')&&mentions.has(part.slice(1))?`<span class="mention" title="${e(mentions.get(part.slice(1)).name)}">${e(part)}</span>`:e(part)).join('');}
async function detailViewV5(key,routeId){
  const data=await api('/tickets/'+encodeURIComponent(key)),t=data.ticket;if(routeId===S.routeId){S.ticket=t;S.ticketSync=data.sync||[];}
  const editable=isStaff()&&!S.portalMode&&t.can_work&&t.status!=='closed'&&!t.project_archived&&!t.archived_at;
  const controls=editable?`<form data-form="ticket-fields">${pick('Priorytet','priority',S.meta.priorities,t.priority)}${pick('Klasyfikacja','type',S.meta.types,t.type)}${pick('Opiekun','assignee_id',agentMap(data.agents),t.assignee_id,'Nieprzypisane')}${saveFooter()}</form>`:statusPill(t);
  return `<div class="ticket-current-status"><span>Bieżący status</span>${statusPill(t)}${t.archived_at?'<span class="pill closed">Archiwum</span>':''}</div>${transitionButtons(t)}<div class="breadcrumb"><a href="#/queue">Zgłoszenia</a><span>/</span><span>${e(t.project_name)}</span></div>${heading(t.key,t.title,editable?'<button data-action="edit-ticket">Edytuj opis</button>':'')}${t.can_work?`<div class="ticket-tools">${ticketToolsV6(t)}${extraButton('clone-ticket','Klonuj zgłoszenie')}${extraButton('link-ticket','Powiąż zgłoszenie')}${editable?extraButton('reporter','Zmień zgłaszającego')+extraButton('attach-asset','Podepnij urządzenie'):''}${(data.sync||[]).map(c=>c.existing?`<a class="button" href="#/ticket/${e(c.existing)}">${e(c.name)} · ${e(c.existing)}</a>`:extraButton('transfer',c.name,`data-id="${c.id}"`)).join('')}</div>`:''}<div class="ticket-layout"><div><section class="panel detail-panel"><h2>Opis</h2><div class="prose">${e(t.description)}</div></section>${customDetails(t)}${t.resolution_text?`<section class="panel detail-panel resolution-panel"><h2>Rozwiązanie</h2><div class="prose">${e(t.resolution_text)}</div></section>`:''}${t.auto_close_at?`<div class="automation-deadline">Planowane zamknięcie: <strong>${date(t.auto_close_at)}</strong></div>`:''}<section class="panel detail-panel"><div class="section-heading"><h2>Rozmowa</h2><span class="count">${data.comments.length}</span></div><div class="conversation">${data.comments.map(c=>`<article class="comment ${c.internal?'internal':''}"><div class="comment-heading"><img class="comment-avatar" src="${e(c.avatar_url||'/favicon.svg')}" alt=""><strong>${e(c.author_name)}</strong>${c.is_bot?'<span class="bot-label">Konto automatyzacji</span>':''}${c.internal?'<span class="private-label">Notatka wewnętrzna</span>':''}<time>${date(c.created_at)}</time></div><div class="prose">${commentMarkup(c)}</div></article>`).join('')||'<p class="hint">Nie ma jeszcze odpowiedzi.</p>'}</div>${t.status!=='closed'&&!t.archived_at&&!t.project_archived&&(t.can_work||!t.customer_reply_locked)?`<form data-form="comment"><label>${t.can_work?'Wiadomość':'Twoja odpowiedź'}<textarea name="body" rows="5" required maxlength="20000" data-mentions placeholder="Napisz odpowiedź. Użyj @, aby oznaczyć osobę."></textarea></label><div id="mention-options" class="mention-options"></div>${t.can_work?check('Notatka wewnętrzna — tylko dla zespołu','internal',false):''}${saveFooter('Dodaj wiadomość')}</form>`:''}</section>${t.can_work?`<section class="panel detail-panel"><h2>Powiązania i urządzenia</h2>${(t.links||[]).map(l=>`<p class="ticket-link-row"><a href="#/ticket/${e(l.key)}">${e(l.key)}</a> · ${e(l.title)} <small>${e(l.kind)}</small>${v6button('unlink','Odłącz',`data-id="${l.id}"`)}</p>`).join('')||'<p class="hint">Brak powiązanych spraw.</p>'}${(t.assets||[]).map(a=>`<p><a href="/#/admin/assets?project=${a.project_id}">${e(a.asset_key)} · ${e(a.name)}</a>${editable?extraButton('remove-asset','Odłącz',`data-id="${a.id}"`):''}</p>`).join('')}</section><section class="panel detail-panel"><h2>Historia zmian</h2><ol class="activity">${(data.activity||[]).map(a=>`<li><div>${e(a.body)}</div><small>${e(a.actor_name)} · ${date(a.created_at)}</small></li>`).join('')}</ol></section>`:''}</div><aside class="ticket-sidebar"><section class="panel detail-panel"><h2>Szczegóły</h2>${controls}<dl><dt>Zgłaszający</dt><dd>${e(t.reporter_name)}</dd><dt>Utworzono</dt><dd>${date(t.created_at)}</dd><dt>Aktualizacja</dt><dd>${date(t.updated_at)}</dd>${t.closed_at?`<dt>Zamknięto</dt><dd>${date(t.closed_at)}</dd>`:''}</dl></section>${t.time?`<section class="panel detail-panel"><h2>${t.time.closed?'Czas do zamknięcia':'Od utworzenia'}</h2><strong class="elapsed-total">${duration(t.time.total_ms)}</strong><dl>${t.time.statuses.map(s=>`<dt>${e(s.name)}</dt><dd>${duration(s.total_ms)}</dd>`).join('')}</dl><p class="hint">Czas kalendarzowy, nie ewidencja roboczogodzin.${t.time.history_complete?'':' Historia statusów sprzed aktualizacji jest niepełna.'}</p></section>`:''}${t.can_work||t.sla?.length?`<section class="panel detail-panel"><h2>SLA</h2>${(t.sla||[]).map(s=>`<div class="sla-block"><span>${e(s.name)}</span><strong class="${s.breached?'overdue':'sla-ok'}">${e({running:'W toku',paused:'Wstrzymane',completed:'Zakończone',stopped:'Zatrzymane',not_started:'Nie rozpoczęto'}[s.state])}${s.breached?' · po terminie':''}</strong>${s.target_ms?`<small>${duration(s.elapsed_ms)} / ${duration(s.target_ms)}</small>`:''}${s.due_at?`<small>Termin: ${date(s.due_at)}</small>`:''}</div>`).join('')}</section>`:''}</aside></div>`;
}
const detailView=detailViewV5;
async function transitionWithResolution(state){const t=S.ticket,x=t.transitions.find(x=>x.to===state);if(!x)throw new Error('Przejście nie jest dostępne.');const target=S.meta.projects.find(p=>p.id===t.project_id)?.workflow_statuses.find(s=>s.key===state);if(target?.category==='closed'||t.resolution_statuses?.includes(state)){showModal(`<h2>${e(x.name)}</h2><p>Podaj wynik obsługi sprawy ${e(t.key)}.</p><form data-extra="resolution" data-state="${e(state)}"><label>Rozwiązanie${t.resolution_required?' *':''}<textarea name="resolution_text" rows="6" maxlength="20000"${t.resolution_required?' required':''}>${e(t.resolution_text)}</textarea></label>${saveFooter('Zapisz i wykonaj przejście')}</form>`);}else await changeTicket({workflow_status:state});}
function baseFieldEditor(f){return `<section class="panel detail-panel"><h2>Temat i opis zgłoszenia</h2><p class="hint">Ukryte pole otrzyma podaną tutaj stałą wartość. Zgłaszający nie musi jej wpisywać.</p>${['title','description'].map(k=>`${check(k==='title'?'Ukryj temat':'Ukryj opis','hide_'+k,f.base_fields?.[k]?.hidden)}<label>${k==='title'?'Stały temat':'Stały opis'}<textarea name="fixed_${k}" rows="${k==='title'?2:4}" maxlength="${k==='title'?200:20000}">${e(f.base_fields?.[k]?.value||'')}</textarea></label>`).join('')}</section>`;}
async function extraProfile(){const p=await api('/desk/profile');return heading('MOJE KONTO',S.user.name)+`<div class="settings-grid"><section class="panel detail-panel"><div class="profile-heading"><img src="/api/avatars/${S.user.id}?v=${S.avatarVersion||S.user.version}" class="profile-photo" alt="Zdjęcie profilu"><div><strong>@${e(S.user.username)}</strong><p>${e(S.user.email)}</p></div></div><form data-extra="avatar"><label>Zdjęcie · PNG, JPEG lub WebP<input name="photo" type="file" accept="image/png,image/jpeg,image/webp" required></label><p class="hint">Do 2 MB.</p>${saveFooter('Zapisz zdjęcie')}</form><form data-extra="theme">${pick('Wygląd aplikacji','theme',{system:'Zgodny z urządzeniem',light:'Jasny',dark:'Ciemny'},S.user.theme||'system')}${saveFooter('Zapisz wygląd')}</form><button data-v7-action="mfa">Weryfikacja dwuetapowa</button>${S.user.auth_source!=='ldap'?'<button data-extra-action="password">Zmień hasło</button>':'<p>Dane tożsamości i hasło są zarządzane przez katalog LDAP.</p>'}</section><section class="panel detail-panel"><h2>Dane osobowe</h2>${S.user.auth_source!=='ldap'?`<form data-extra="profile-name">${input('Imię','first_name',S.user.first_name,'required maxlength="60"')}${input('Nazwisko','last_name',S.user.last_name,'maxlength="80"')}<p class="hint">Zmiana wymaga zatwierdzenia administratora. Nazwa konta pozostanie taka sama.</p>${saveFooter('Wyślij do zatwierdzenia')}</form><h2>Zmiana adresu e-mail</h2><form data-extra="profile-email">${input('Nowy e-mail','email','','type="email" required')}${pick('Czy masz dostęp do obecnego adresu?','old_access',{yes:'Tak — potwierdzę kodem',no:'Nie — proszę administratora'},'yes')}<label>Uzasadnienie (gdy nie masz dostępu)<textarea name="note" rows="3" maxlength="2000"></textarea></label>${saveFooter('Rozpocznij zmianę')}</form>`:'<p>Imię, nazwisko i adres e-mail pochodzą z LDAP.</p>'}</section></div><section class="panel detail-panel"><h2>Powiadomienia i prośby</h2>${p.notifications.map(n=>`<p>${n.ticket_key?`<a href="#/ticket/${e(n.ticket_key)}">${e(n.body)}</a>`:e(n.body)} <small>${date(n.created_at)}</small></p>`).join('')||'<p>Brak powiadomień.</p>'}${p.requests.map(r=>`<p>${r.kind==='name'?'Zmiana danych osobowych':'Zmiana adresu'} · ${e({pending:'Oczekuje',approved:'Zatwierdzono',rejected:'Odrzucono'}[r.state])}</p>`).join('')}</section>`;}
async function extraAdmin(section,search=new URLSearchParams()){
  if(!extraNames[section])return empty('Nieznany moduł');if(!isStaff())return empty('Moduł dostępny zespołowi');if(['sso','mail','organizations','approvals','events'].includes(section)&&S.user.role!=='admin')return empty('Moduł dostępny administratorowi');
  const endpoint=section==='approvals'?'profile-requests':section,rows=await api('/desk/'+endpoint+(section==='assets'&&search.get('project')?'?project='+search.get('project'):''));S.assetProject=Number(search.get('project'))||null;S.extra={section,rows};
  const createAllowed=!['approvals','events'].includes(section)&&(section!=='templates'||S.user.role==='admin');
  return heading('ADMINISTRACJA I MODUŁY',extraNames[section],`<div class="button-row"><a class="button" href="#/settings">Ustawienia</a>${createAllowed?extraButton('extra-edit','Dodaj',`data-section="${section}"`):''}</div>`)+`<p class="lead">${({sync:'Wybierz parę projektów, autora odpowiedzi i mapowanie statusów. Brak mapowania oznacza brak zmiany statusu.',mail:'Każdy zespół może mieć osobną skrzynkę. Wiadomości i odpowiedzi są powiązane ze zgłoszeniami.',sso:'Podłącz Keycloak, Microsoft Entra ID, Google lub innego dostawcę OpenID Connect.',templates:'Zapisuj i klonuj wspólne obiegi. Zastosowanie szablonu nie usuwa reguł projektu.',organizations:'Grupy klientów z opcjonalnym wspólnym widokiem zgłoszeń firmy.',webhooks:'Zdarzenia wychodzące i uwierzytelnione wyzwalacze automatyzacji.',assets:'Urządzenia, właściciele i powiązane zgłoszenia.',approvals:'Sprawdź wnioski o zmianę imienia, nazwiska lub adresu e-mail.',events:'Nieudane operacje modułów. Po poprawieniu konfiguracji możesz je ponowić.'})[section]}</p><section class="panel table-scroll"><table><thead><tr><th>Nazwa / sprawa</th><th>Szczegóły</th><th>Działania</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${e(r.name||r.key||r.event)}</strong>${r.asset_key?`<small class="row-meta">${e(r.asset_key)}</small>`:''}</td><td>${section==='approvals'?`${e(r.kind==='name'?(r.payload.first_name+' '+r.payload.last_name):r.payload.email)}<p>${e(r.payload.note||'')}</p>${e(r.state)}`:section==='events'?e(r.error):section==='assets'?e(r.kind+' · '+r.status+' · '+r.serial):section==='mail'?`${e(r.email)}<small class="row-meta">${r.last_error?e(r.last_error):'Ostatni odczyt: '+date(r.last_poll)}</small>`:section==='sync'?e(S.meta.projects.find(p=>p.id===r.source_project)?.name+' → '+S.meta.projects.find(p=>p.id===r.target_project)?.name):section==='organizations'?`${r.members?.length||0} osób · ${r.share_tickets?'Wspólne zgłoszenia':'Własne zgłoszenia'}`:section==='sso'?e(r.issuer):section==='webhooks'?e(r.direction==='inbound'?'Przychodzący':'Wychodzący'):r.is_default?'Domyślny szablon':''}${r.enabled!==undefined?`<small class="row-meta">${r.enabled?'Aktywne':'Wyłączone'}</small>`:''}</td><td><div class="button-row">${section==='approvals'?(r.state==='pending'?extraButton('approve-profile','Zatwierdź',`data-id="${r.id}"`)+extraButton('reject-profile','Odrzuć',`data-id="${r.id}"`):''):section==='events'?extraButton('retry-event','Ponów',`data-id="${r.id}"`):extraButton('extra-edit','Edytuj',`data-id="${r.id}" data-section="${section}"`)}${section==='templates'?extraButton('template-apply','Zastosuj',`data-id="${r.id}"`)+(S.user.role==='admin'?extraButton('template-clone','Klonuj',`data-id="${r.id}"`):''):''}${section==='sso'?extraButton('sso-map','Powiąż konto',`data-id="${r.id}"`):''}${section==='assets'?extraButton('asset-ticket','Utwórz zgłoszenie',`data-id="${r.id}"`):''}</div></td></tr>`).join('')||'<tr><td colspan="3">Brak wpisów. Dodaj pierwszy element.</td></tr>'}</tbody></table></section>${section==='mail'?await mailReceiptsView():section==='webhooks'?await webhookJobsView():''}`;
}
async function mailReceiptsView(){const rows=await api('/desk/mail/receipts');return `<section class="panel detail-panel"><h2>Odbiór wiadomości</h2>${rows.map(r=>`<p>${e(r.channel_name)} · ${date(r.created_at)} · ${e(r.status)}<small class="row-meta">${e(r.detail)}</small></p>`).join('')||'<p>Nie przetworzono jeszcze wiadomości.</p>'}</section>`;}
async function webhookJobsView(){const rows=await api('/desk/webhooks/jobs');return `<section class="panel detail-panel"><h2>Dostarczenie webhooków</h2>${rows.map(r=>`<p>#${r.id} · ${e(r.status)} · próby: ${r.attempts} ${e(r.last_error||'')}</p>`).join('')||'<p>Brak wysyłek.</p>'}</section>`;}
function syncMappingRow(m={},direction='to_target',source,target){const states=id=>Object.fromEntries((S.meta.projects.find(p=>p.id===Number(id))?.workflow_statuses||[]).map(s=>[s.key,s.name]));return `<div class="sync-map form-row" data-direction="${direction}">${pick('Status źródłowy','map_from',states(source),m.from)}${pick('Status docelowy','map_to',states(target),m.to)}${extraButton('remove-row','Usuń')}</div>`;}
async function extraEdit(section,id){
  const r=S.extra?.section===section?S.extra.rows.find(r=>r.id===Number(id))||{}:{},c=r.config||{},projects=S.meta.projects.filter(p=>p.can_manage||section==='assets'&&p.can_work),pmap=Object.fromEntries(projects.filter(p=>section==='assets'?p.project_type==='assets':p.project_type!=='assets').map(p=>[p.id,p.name]));
  const users=S.user.role==='admin'?await api('/users'):section==='assets'?(await api('/desk/people')).map(u=>({...u,active:true})):[],umap=Object.fromEntries(users.filter(u=>u.active).map(u=>[u.id,u.name+' · @'+u.username])),bots=Object.fromEntries(users.filter(u=>u.active).map(u=>[u.id,u.name]));let body='';
  if(['sync','webhooks'].includes(section)&&!users.length){const agents=await Promise.all(projects.map(p=>api('/projects/'+p.id+'/agents')));for(const a of agents.flat()){umap[a.id]=a.name;if(a.active!==false)bots[a.id]=a.name;}}
  if(section==='sync'){const source=r.source_project||projects[0]?.id,target=r.target_project||projects.find(p=>p.id!==source)?.id;body=`${input('Nazwa przycisku','name',r.name,'required placeholder="np. Wyślij do IT Adminów"')}<div class="form-row">${pick('Projekt źródłowy','source_project',pmap,source)}${pick('Projekt docelowy','target_project',pmap,target)}</div>${pick('Autor zsynchronizowanych odpowiedzi','author_id',umap,c.author_id)}<p class="hint">Wybrane konto musi mieć dostęp zespołowy do obu projektów. Rzeczywisty autor pozostanie w audycie.</p>${pick('Synchronizuj nowe komentarze','comments',{none:'Wyłączone',to_source:'Docelowy → źródłowy',to_target:'Źródłowy → docelowy',both:'W obie strony'},c.comments||'to_source')}${check('Kopiuj także notatki wewnętrzne (pozostaną wewnętrzne)','internal_notes',c.internal_notes)}<label>Formularz docelowy<select name="request_type_id" data-channel-form>${options({},null,'Domyślny dla klasyfikacji')}</select></label><h3>Statusy: źródłowy → docelowy</h3><div id="maps-to-target">${(c.to_target||[]).map(m=>syncMappingRow(m,'to_target',source,target)).join('')}</div>${extraButton('add-map','Dodaj mapowanie','data-direction="to_target"')}<h3>Statusy: docelowy → źródłowy</h3><div id="maps-to-source">${(c.to_source||[]).map(m=>syncMappingRow(m,'to_source',target,source)).join('')}</div>${extraButton('add-map','Dodaj mapowanie','data-direction="to_source"')}${check('Synchronizacja aktywna','enabled',r.enabled??true)}`;}
  if(section==='mail')body=mailEditorV6(r,c,pmap);
  if(section==='sso')body=`${input('Nazwa przycisku logowania','name',r.name,'required placeholder="Konto firmowe"')}${input('Issuer OpenID Connect','issuer',r.issuer,'type="url" required placeholder="https://sso.example.com/realms/firmowe"')}${input('Client ID','client_id',r.client_id,'required')}${input('Client secret','client_secret','','type="password" autocomplete="new-password" placeholder="Puste = zachowaj zapisany sekret"')}<p class="hint">Adres przekierowania w dostawcy: <code>${e(location.origin)}/api/sso/callback</code></p>${check('Twórz nowe konta klientów ze zweryfikowanym e-mailem','auto_create',c.auto_create)}${input('Dopuszczone domeny (po przecinku)','allowed_domains',(c.allowed_domains||[]).join(', '))}${check('SSO aktywne','enabled',r.enabled)}<p class="hint">Istniejące konto musi zostać powiązane przez administratora. Sam zgodny adres e-mail nie łączy kont.</p>`;
  if(section==='organizations')body=`${input('Nazwa firmy / grupy','name',r.name,'required')}${check('Członkowie widzą zgłoszenia przypisane do tej firmy','share_tickets',r.share_tickets)}${multi('Członkowie','members',Object.fromEntries(users.filter(u=>true).map(u=>[u.id,u.name+' · '+u.email])),r.members)}${multi('Projekty z portalem','projects',Object.fromEntries(projects.filter(p=>p.project_type==='external').map(p=>[p.id,p.name])),r.projects)}`;
  if(section==='templates')body=`${input('Nazwa szablonu','name',r.name,'required')}${pick('Kopiuj statusy i przejścia z projektu','project_id',pmap,null)}${check('Domyślny obieg dla nowych projektów','is_default',r.is_default)}<p class="hint">Szablon obejmuje statusy i przejścia. Reguły pozostają ustawieniami konkretnego projektu.</p>`;
  if(section==='webhooks')body=`${input('Nazwa','name',r.name,'required')}${pick('Projekt','project_id',pmap,r.project_id)}${pick('Kierunek','direction',{inbound:'Przychodzący — wyzwala reguły',outbound:'Wychodzący — powiadamia inny system'},r.direction||'inbound')}${input('Adres docelowy (dla wychodzącego)','url',c.url,'type="url"')}${multi('Zdarzenia wychodzące','events',{ticket_created:'Utworzenie sprawy',status_changed:'Zmiana statusu',comment_added:'Komentarz'},c.events)}${pick('Konto automatyzacji dla przychodzącego','bot_id',bots,c.bot_id,'Wybierz')}${check('Uwzględniaj notatki wewnętrzne','include_internal',c.include_internal)}${check('Dopuść docelową sieć prywatną','allow_private',c.allow_private)}${check('Wygeneruj nowy sekret','rotate_secret',false)}${check('Aktywny','enabled',r.enabled??true)}`;
  if(section==='assets')body=`${pick('Katalog urządzeń','project_id',pmap,r.project_id)}${input('Nazwa urządzenia','name',r.name,'required')}${input('Typ urządzenia','kind',r.kind||'Laptop','required')}${input('Numer seryjny','serial',r.serial)}${pick('Właściciel','owner_id',umap,r.owner_id,'Nieprzypisany')}${input('Stan urządzenia','status',r.status||'W użyciu','required')}<h3>Dodatkowe właściwości</h3><div id="asset-properties">${Object.entries(r.data||{}).map(([key,value])=>assetProperty(key,value)).join('')}</div>${extraButton('asset-property','Dodaj właściwość')}`;
  showModal(`<h2>${r.id?'Edytuj':'Dodaj'} · ${e(extraNames[section])}</h2><form data-extra="module" data-section="${section}" data-id="${r.id||''}" data-version="${r.version||0}">${body}${saveFooter()}</form>`);modal.classList.add('wide-modal');if(section==='mail')updateMailMode($('[data-extra="module"]',modal));if(['mail','sync'].includes(section))await loadChannelForms(c.request_type_id);
}
function assetProperty(key='',value=''){return `<div class="asset-property form-row">${input('Właściwość','property_key',key,'required maxlength="100"')}${input('Wartość','property_value',value,'maxlength="1000"')}${extraButton('remove-row','Usuń')}</div>`;}
async function loadChannelForms(selectedId){const f=$('[data-extra="module"]',modal);if(!f)return;const pid=f.elements.project_id?.value||f.elements.target_project?.value,select=f.elements.request_type_id;if(!pid||!select)return;const rows=await api('/projects/'+pid+'/request-types?surface=manage');select.innerHTML=options(Object.fromEntries(rows.filter(r=>r.enabled).map(r=>[r.id,r.name])),selectedId,f.dataset.section==='sync'?'Domyślny dla klasyfikacji':undefined);}
function slaRuleEditor(r={},map){return `<fieldset class="sla-rule" data-id="${e(r.id||freshKey('sla'))}"><legend>Miernik SLA</legend>${input('Nazwa','sla_name',r.name||'Czas rozwiązania','required')}${pick('Pomiar','sla_kind',{status:'Do osiągnięcia statusu',first_response:'Do pierwszej odpowiedzi zespołu'},r.kind||'status')}<div class="form-row">${Object.keys(S.meta.priorities).map(k=>input(k+' · minuty','goal_'+k,r.goals?.[k]||60,'type="number" min="1" max="525600" required')).join('')}</div>${multi('Start — puste = utworzenie sprawy','sla_start',map,r.start)}${multi('Pauza w statusach','sla_pause',map,r.pause)}${multi('Zakończenie w statusach','sla_stop',map,r.stop)}${check('Nowe wejście w status początkowy uruchamia nowy pomiar','sla_reset',r.reset_on_start)}${check('Pokaż ten miernik klientowi','sla_customer',r.visible_to_customer??false)}${multi('Tylko formularze (puste = wszystkie)','sla_forms',S.slaForms||{},r.request_type_ids)}${extraButton('remove-row','Usuń miernik')}</fieldset>`;}
async function extraProjectSettings(p,slaOnly=false){const cfg=p.settings||{},map=Object.fromEntries(p.workflow_statuses.map(s=>[s.key,s.name]));S.slaForms=Object.fromEntries((await api('/projects/'+p.id+'/request-types?surface=manage')).map(f=>[f.id,f.name]));const sla=cfg.sla||{timezone:'Europe/Warsaw',week:Object.fromEntries([1,2,3,4,5,6,7].map(d=>[d,[['00:00','24:00']]])),holidays:[],rules:[{id:'response',name:'Pierwsza odpowiedź',kind:'first_response',goals:Object.fromEntries(Object.keys(S.meta.priorities).map(k=>[k,p.sla_policy[k][0]]))},{id:'resolution',name:'Rozwiązanie',kind:'status',goals:Object.fromEntries(Object.keys(S.meta.priorities).map(k=>[k,p.sla_policy[k][1]])),stop:p.workflow_statuses.filter(s=>['resolved','closed'].includes(s.category)).map(s=>s.key)}]};
  return `<form data-extra="project-options" data-id="${p.id}" data-version="${p.version}" data-sla-only="${slaOnly}">${!slaOnly?`<section class="panel detail-panel"><h2>Zamykanie, powiadomienia i urządzenia</h2><p>Powiadomienia o nowej sprawie otrzymują osoby przypisane w zakładce Zespół jako agenci lub kierownicy. Wymagana jest działająca poczta SMTP.</p><a class="button" href="#/admin/mail-templates">Edytuj szablony i wyzwalacze e-mail</a>${multi('Pokaż okno rozwiązania przy statusach','resolution_statuses',map,cfg.resolution_statuses)}${check('Rozwiązanie jest wymagane','resolution_required',cfg.resolution_required)}<p class="hint">Status z kategorii „Zamknięte” zawsze wyświetla okno rozwiązania i jest ostateczny.</p>${check('Automatycznie obserwuj zgłoszenia po działaniach agenta','auto_watch',cfg.auto_watch??true)}${check('Powiadamiaj kierowników o nowej sprawie','notify_new_managers',cfg.notify_new_managers??false)}${check('Powiadamiaj zespół o nowej sprawie','notify_new_team',cfg.notify_new_team??false)}${check('Pokazuj czas w statusach i czas trwania sprawy','time_tracking',cfg.time_tracking??true)}${multi('Zezwalaj na urządzenia z katalogów','asset_projects',Object.fromEntries(S.meta.projects.filter(p=>(p.project_type==='assets'||p.module_type==='assets')&&p.can_work).map(p=>[p.id,p.name])),cfg.asset_projects)}</section><section class="panel detail-panel"><h2>Wygląd portalu</h2>${input('Dodatkowe powitanie','portal_welcome',cfg.portal?.welcome,'maxlength="3000"')}${input('Stopka','portal_footer',cfg.portal?.footer,'maxlength="1000"')}${pick('Układ formularzy','portal_layout',{cards:'Kafelki',list:'Lista'},cfg.portal?.layout||'cards')}${pick('Kolor przewodni','portal_accent',{blue:'Niebieski',teal:'Turkusowy',violet:'Fioletowy',orange:'Pomarańczowy'},cfg.portal?.accent||'blue')}${check('Pokazuj ostatnie zgłoszenia','portal_recent',cfg.portal?.show_recent??true)}${check('Pokazuj wyszukiwanie zgłoszeń','portal_search',cfg.portal?.show_search??true)}</section>`:`<section class="panel detail-panel"><h2>Kalendarz SLA</h2>${input('Strefa czasowa','sla_timezone',sla.timezone,'required placeholder="Europe/Warsaw"')}<div class="calendar-week">${['Poniedziałek','Wtorek','Środa','Czwartek','Piątek','Sobota','Niedziela'].map((n,i)=>input(n,'day_'+(i+1),(sla.week[i+1]||[]).map(a=>a.join('–')).join(', '),'placeholder="09:00–17:00; puste = wolne"')).join('')}</div><p class="hint">Kilka przedziałów rozdziel przecinkami. Godziny lokalne wybranej strefy, z uwzględnieniem zmiany czasu.</p><label>Dni wolne (YYYY-MM-DD, po jednym wierszu)<textarea name="holidays" rows="4">${e((sla.holidays||[]).join('\n'))}</textarea></label></section><section class="panel detail-panel"><h2>Mierniki SLA</h2><div id="sla-rules">${sla.rules.map(r=>slaRuleEditor(r,map)).join('')}</div>${extraButton('add-sla','Dodaj miernik')}<p class="hint">Zmiana celów przelicza widok istniejących spraw. Historia sprzed aktualizacji pozostaje oznaczona jako niepełna.</p></section>`}${saveFooter('Zapisz ustawienia projektu')}</form>`;
}
async function reporterOptions(form,projectId,selectedId=S.user.id){const rows=await api('/desk/projects/'+projectId+'/reporters?q='+encodeURIComponent(form.elements.reporter_search?.value||''));const select=form.elements.reporter_id;if(select){select.innerHTML=options(Object.fromEntries(rows.map(u=>[u.id,u.name+' · '+u.email])),selectedId);if(!select.options.length)select.innerHTML='<option value="">Brak osób — zmień wyszukiwanie</option>';}}
async function organizationOptions(form,projectId){const rows=await api('/desk/organizations'),select=form.elements.organization_id;if(select)select.innerHTML=options(Object.fromEntries(rows.filter(o=>o.projects?.includes(Number(projectId))&&o.members?.includes(Number(form.elements.reporter_id?.value||S.user.id))).map(o=>[o.id,o.name])),null,'Tylko zgłaszający');}
async function extraAction(action,button){const id=Number(button.dataset.id),section=button.dataset.section;
  if(action==='profile-open'){location.hash='#/profile';return;}
  if(action==='extra-edit')return extraEdit(section,id);
  if(action==='remove-row'){button.closest('.sync-map,.asset-property,.sla-rule').remove();return;}
  if(action==='asset-property'){$('#asset-properties').insertAdjacentHTML('beforeend',assetProperty());return;}
  if(action==='password'){showModal(passwordForm());return;}
  if(action==='add-map'){const f=button.closest('form'),direction=button.dataset.direction,source=f.elements.source_project.value,target=f.elements.target_project.value;$('#maps-'+(direction==='to_target'?'to-target':'to-source')).insertAdjacentHTML('beforeend',syncMappingRow({},direction,direction==='to_target'?source:target,direction==='to_target'?target:source));return;}
  if(action==='add-sla'){$('#sla-rules').insertAdjacentHTML('beforeend',slaRuleEditor({},Object.fromEntries(S.project.workflow_statuses.map(s=>[s.key,s.name]))));return;}
  if(['approve-profile','reject-profile'].includes(action)){await api('/desk/profile-requests/'+id,{method:'POST',data:{approve:action==='approve-profile'}});notify('Zapisano decyzję.');return route();}
  if(action==='retry-event'){await api('/desk/events/'+id,{method:'POST',data:{}});return route();}
  if(action==='reporter'){showModal(`<h2>Zmień zgłaszającego · ${e(S.ticket.key)}</h2><form data-extra="reporter">${input('Szukaj osoby','reporter_search','','data-reporter-search maxlength="100"')}<label>Zgłaszający<select name="reporter_id" required></select></label><label>Widoczność w firmie<select name="organization_id"><option value="">Tylko zgłaszający</option></select></label><p class="hint">Historia zachowa osobę wykonującą zmianę i poprzedniego zgłaszającego.</p>${saveFooter()}</form>`);const f=$('[data-extra="reporter"]');await reporterOptions(f,S.ticket.project_id,S.ticket.reporter_id);await organizationOptions(f,S.ticket.project_id);return;}
  if(action==='clone-ticket'){showModal(`<h2>Klonuj ${e(S.ticket.key)}</h2><form data-extra="clone-ticket">${pick('Projekt docelowy','project_id',Object.fromEntries(S.meta.projects.filter(p=>p.can_work&&p.project_type!=='assets'&&!p.archived).map(p=>[p.id,p.name])),S.ticket.project_id)}<p>Kopia zachowa opis i pasujące dane formularza. Powstanie nowe zgłoszenie oraz wewnętrzne powiązanie z oryginałem.</p>${saveFooter('Utwórz kopię')}</form>`);return;}
  if(action==='link-ticket'){showModal(`<h2>Powiąż ze sprawą</h2><form data-extra="link-ticket">${input('Numer istniejącego zgłoszenia','key','','required autocomplete="off" role="combobox" aria-autocomplete="list" aria-controls="link-options" aria-expanded="false" data-link-search placeholder="CW-000"')}<div id="link-options" class="link-options" role="listbox"></div><p class="hint">Wpisz klucz i co najmniej 3 cyfry, np. CW-000. Możesz też podać pełny krótszy numer.</p><p>Powiązanie zobaczą wyłącznie pracownicy mający dostęp do obu spraw.</p>${saveFooter('Dodaj powiązanie')}</form>`);return;}
  if(action==='transfer'){button.disabled=true;const r=await api('/desk/tickets/'+S.ticket.id+'/transfer',{method:'POST',data:{config_id:id}});notify('Utworzono i powiązano '+r.key);return route();}
  if(action==='attach-asset'){const all=await api('/desk/assets'),allowed=S.meta.projects.find(p=>p.id===S.ticket.project_id)?.settings?.asset_projects||[],rows=all.filter(a=>allowed.includes(a.project_id));showModal(`<h2>Podepnij urządzenie</h2>${!rows.length?`<p>Brak dostępnych urządzeń. W ustawieniach projektu włącz odpowiedni katalog.</p><a class="button" href="#/project/${S.ticket.project_id}?tab=options" data-v71-action="asset-settings">Ustawienia projektu</a>`:''}<form data-extra="attach-asset">${pick('Urządzenie','asset_id',Object.fromEntries(rows.map(a=>[a.id,a.asset_key+' · '+a.name])),null)}<p class="hint">Dostępne katalogi wybiera kierownik w ustawieniach projektu.</p>${rows.length?saveFooter('Podepnij'):''}</form>`);return;}
  if(action==='remove-asset'){await api('/desk/tickets/'+S.ticket.id+'/asset',{method:'POST',data:{asset_id:id,remove:true}});return route();}
  if(action==='asset-ticket'){const a=S.extra.rows.find(r=>r.id===id),p=S.meta.projects.find(p=>p.can_work&&!p.archived&&p.settings?.asset_projects?.includes(a.project_id));if(!p)throw new Error('Najpierw dopuść ten katalog urządzeń w ustawieniach projektu zgłoszeń.');await createTicketModal(p.id,undefined,false);$('[data-form="create-ticket"]',modal)._assetId=a.id;return;}
  if(action==='template-clone'){showModal(`<h2>Klonuj szablon statusów</h2><form data-extra="template-clone" data-id="${id}">${input('Nazwa kopii','name','','required')}${saveFooter('Klonuj')}</form>`);return;}
  if(action==='template-apply'){showModal(`<h2>Zastosuj szablon</h2><form data-extra="template-apply" data-id="${id}">${pick('Projekt','project_id',Object.fromEntries(S.meta.projects.filter(p=>p.can_manage).map(p=>[p.id,p.name])),null)}<p>Reguły projektu pozostają zachowane. Statusy używane przez zgłoszenia muszą pozostać zgodne z szablonem.</p>${saveFooter('Zastosuj')}</form>`);return;}
  if(action==='sso-map'){const users=await api('/users');showModal(`<h2>Powiąż tożsamość SSO</h2><form data-extra="sso-map" data-id="${id}">${input('Identyfikator użytkownika u dostawcy (sub)','subject','','required maxlength="300"')}${pick('Istniejące konto','user_id',Object.fromEntries(users.filter(u=>u.account_kind==='human').map(u=>[u.id,u.name+' · '+u.email])),null)}<p class="hint">W Keycloak identyfikatorem sub jest ID użytkownika z konsoli administracyjnej. Powiązanie nadaje logowaniu SSO dostęp do wybranego konta.</p>${saveFooter('Powiąż')}</form>`);return;}
  if(action==='mention'){const area=$('[data-mentions]'),before=area.value.slice(0,area.selectionStart),after=area.value.slice(area.selectionStart),next=before.replace(/@[\w.-]*$/,'@'+button.dataset.username+' ');area.value=next+after;area.focus();area.setSelectionRange(next.length,next.length);$('#mention-options').innerHTML='';return;}
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-extra-action]');if(!button)return;event.preventDefault();void extraAction(button.dataset.extraAction,button).catch(err=>{button.disabled=false;notify(err.message,true);});});
let mentionTimer,reporterTimer;
document.addEventListener('input',event=>{
  if(event.target.matches('[data-mentions]')){clearTimeout(mentionTimer);const area=event.target,match=area.value.slice(0,area.selectionStart).match(/@([\w.-]*)$/);if(!match){$('#mention-options').innerHTML='';return;}mentionTimer=setTimeout(async()=>{try{const list=await api('/desk/mentions?ticket='+S.ticket.id+'&q='+encodeURIComponent(match[1]));if(area.isConnected)$('#mention-options').innerHTML=list.map(u=>extraButton('mention',u.name+' · @'+u.username,`data-username="${e(u.username)}"`)).join('');}catch(err){notify(err.message,true);}},200);}
  if(event.target.matches('[data-reporter-search]')){clearTimeout(reporterTimer);const f=event.target.closest('form');reporterTimer=setTimeout(()=>void reporterOptions(f,Number(f.elements.project_id?.value||S.ticket.project_id)).catch(err=>notify(err.message,true)),250);}
});
document.addEventListener('change',event=>{const f=event.target.closest('form');if(!f)return;
  if(f.dataset.extra==='module'&&['project_id','target_project','source_project'].includes(event.target.name)){if(['mail','sync'].includes(f.dataset.section))void loadChannelForms().catch(err=>notify(err.message,true));if(f.dataset.section==='sync'){for(const el of f.querySelectorAll('.sync-map'))el.remove();}}
  if(event.target.name==='reporter_id')void organizationOptions(f,Number(f.elements.project_id?.value||S.ticket.project_id)).catch(err=>notify(err.message,true));
});
async function extraSubmit(form){const f=Object.fromEntries(new FormData(form)),id=Number(form.dataset.id),kind=form.dataset.extra;let result;
  if(kind==='resolution'){await changeTicket({workflow_status:form.dataset.state,resolution_text:f.resolution_text});modal.close();return;}
  if(kind==='reporter'){await changeTicket({reporter_id:Number(f.reporter_id),organization_id:f.organization_id?Number(f.organization_id):null});modal.close();return;}
  if(kind==='theme'){result=await api('/desk/profile/theme',{method:'POST',data:{theme:f.theme}});S.user.theme=result.theme;applyTheme();notify('Zapisano motyw.');return;}
  if(kind==='avatar'){const file=form.elements.photo.files[0];if(!file||file.size>2*1024*1024)throw new Error('Wybierz zdjęcie o rozmiarze do 2 MB.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await api('/desk/profile/avatar',{method:'POST',data:{data}});S.avatarVersion=Date.now();notify('Zapisano zdjęcie.');return route();}
  if(kind==='profile-name'){result=await api('/desk/profile/name',{method:'POST',data:f});notify(result.message);return route();}
  if(kind==='profile-email'){if(f.old_access==='no'){result=await api('/desk/profile/email-request',{method:'POST',data:f});notify(result.message);return route();}result=await api('/desk/profile/email-start',{method:'POST',data:{email:f.email}});emailCodeForm(result);return;}
  if(kind==='email-code'){result=await api('/desk/profile/email-code',{method:'POST',data:{token:form.dataset.token,code:f.code}});if(result.step==='done'){S.user=null;S.csrf='';modal.close();authResult(result.message);}else emailCodeForm(result);return;}
  if(kind==='invite'){if(f.password!==f.repeat)throw new Error('Hasła muszą być identyczne.');result=await api('/accept-invite',{method:'POST',data:{token:form.dataset.token,password:f.password}});authResult(result.message);return;}
  if(kind==='clone-ticket'){result=await api('/desk/tickets/'+S.ticket.id+'/clone',{method:'POST',data:{project_id:Number(f.project_id)}});modal.close();notify('Utworzono '+result.key);await refreshMeta();location.hash='#/ticket/'+result.key;return;}
  if(kind==='link-ticket'){await api('/desk/tickets/'+S.ticket.id+'/link',{method:'POST',data:{key:f.key.trim().toUpperCase()}});modal.close();return route();}
  if(kind==='attach-asset'){await api('/desk/tickets/'+S.ticket.id+'/asset',{method:'POST',data:{asset_id:Number(f.asset_id)}});modal.close();return route();}
  if(kind==='template-clone'){await api('/desk/templates/'+id+'/clone',{method:'POST',data:{name:f.name}});modal.close();return route();}
  if(kind==='template-apply'){const current=await api('/projects/'+f.project_id+'/workflow');await api('/desk/templates/'+id+'/apply',{method:'POST',data:{project_id:Number(f.project_id),version:current.version}});modal.close();notify('Zastosowano obieg.');await refreshMeta();return route();}
  if(kind==='sso-map'){await api('/desk/sso/'+id+'/mapping',{method:'POST',data:{subject:f.subject,user_id:Number(f.user_id)}});modal.close();notify('Powiązano tożsamość.');return;}
  if(kind==='project-options'){let data={version:Number(form.dataset.version)};if(form.dataset.slaOnly==='true'){const week={};for(let d=1;d<=7;d++)week[d]=(f['day_'+d]||'').split(',').map(s=>s.trim()).filter(Boolean).map(s=>s.split(/[–-]/).map(v=>v.trim()));data.sla={timezone:f.sla_timezone,week,holidays:f.holidays.split(/[\s,;]+/).filter(Boolean),rules:[...form.querySelectorAll('.sla-rule')].map(el=>{const val=n=>$('[name="'+n+'"]',el).value,multi=n=>[...$('[name="'+n+'"]',el).selectedOptions].map(o=>o.value);return {id:el.dataset.id,name:val('sla_name'),kind:val('sla_kind'),goals:Object.fromEntries(Object.keys(S.meta.priorities).map(k=>[k,Number(val('goal_'+k))])),start:multi('sla_start'),pause:multi('sla_pause'),stop:multi('sla_stop'),reset_on_start:$('[name="sla_reset"]',el).checked,visible_to_customer:$('[name="sla_customer"]',el).checked,request_type_ids:multi('sla_forms').map(Number)};})};}else data={...data,auto_watch:f.auto_watch==='on',notify_new_managers:f.notify_new_managers==='on',notify_new_team:f.notify_new_team==='on',resolution_required:f.resolution_required==='on',resolution_statuses:selected(form,'resolution_statuses'),time_tracking:f.time_tracking==='on',asset_projects:selected(form,'asset_projects').map(Number),portal:{welcome:f.portal_welcome,footer:f.portal_footer,layout:f.portal_layout,accent:f.portal_accent,show_recent:f.portal_recent==='on',show_search:f.portal_search==='on'}};await api('/desk/projects/'+id+'/settings',{method:'PATCH',data});notify('Zapisano ustawienia.');await refreshMeta();return route();}
  if(kind==='module'){const section=form.dataset.section,data={name:f.name,version:Number(form.dataset.version)},domains=s=>(s||'').split(/[\s,;]+/).filter(Boolean);
    if(section==='sync'){Object.assign(data,{source_project:Number(f.source_project),target_project:Number(f.target_project),enabled:f.enabled==='on',config:{author_id:Number(f.author_id),comments:f.comments,internal_notes:f.internal_notes==='on',request_type_id:f.request_type_id?Number(f.request_type_id):null}});for(const direction of ['to_source','to_target'])data.config[direction]=[...form.querySelectorAll('.sync-map[data-direction="'+direction+'"]')].map(el=>({from:$('[name="map_from"]',el).value,to:$('[name="map_to"]',el).value}));}
    if(section==='mail'){Object.assign(data,{project_id:Number(f.project_id),email:f.email,enabled:f.enabled==='on',config:{smtp_mode:'custom',imap_enabled:f.imap_enabled==='on',folder:f.folder,request_type_id:Number(f.request_type_id),allow_new_senders:f.allow_new_senders==='on',start_from_now:f.start_from_now==='on',allowed_domains:domains(f.allowed_domains)}});for(const proto of ['imap','smtp'])Object.assign(data.config,{[proto+'_host']:f[proto+'_host'],[proto+'_port']:Number((f[proto+'_port']||(proto==='smtp'?587:993))),[proto+'_user']:f[proto+'_user'],[proto+'_pass']:f[proto+'_pass'],[proto+'_secure']:f[proto+'_secure']==='on'});}
    if(section==='sso')Object.assign(data,{issuer:f.issuer,client_id:f.client_id,client_secret:f.client_secret,enabled:f.enabled==='on',config:{auto_create:f.auto_create==='on',allowed_domains:domains(f.allowed_domains)}});
    if(section==='organizations')Object.assign(data,{share_tickets:f.share_tickets==='on',members:selected(form,'members').map(Number),projects:selected(form,'projects').map(Number)});
    if(section==='templates')Object.assign(data,{project_id:Number(f.project_id),is_default:f.is_default==='on'});
    if(section==='webhooks')Object.assign(data,{project_id:Number(f.project_id),direction:f.direction,rotate_secret:f.rotate_secret==='on',enabled:f.enabled==='on',config:{url:f.url,bot_id:f.bot_id?Number(f.bot_id):null,events:selected(form,'events'),include_internal:f.include_internal==='on',allow_private:f.allow_private==='on'}});
    if(section==='assets')Object.assign(data,{project_id:Number(f.project_id),kind:f.kind,serial:f.serial,status:f.status,owner_id:f.owner_id?Number(f.owner_id):null,data:Object.fromEntries([...form.querySelectorAll('.asset-property')].map(el=>[$('[name="property_key"]',el).value,$('[name="property_value"]',el).value]))});
    result=await api('/desk/'+section+(id?'/'+id:''),{method:id?'PATCH':'POST',data});modal.close();notify('Zapisano ustawienia.');await refreshMeta();await route();if(result.generated_secret)showModal(`<h2>Sekret webhooka</h2><p>Zapisz go teraz — nie będzie ponownie wyświetlany.</p><textarea readonly rows="3">${e(result.generated_secret)}</textarea>${result.direction==='inbound'?`<p>POST <code>${e(location.origin)}/api/hooks/${result.id}</code></p><p>Nagłówek: <code>Authorization: Bearer SEKRET</code></p><p>Treść: <code>{"event_id":"unikalny-numer","ticket_key":"CW-1"}</code></p>`:'<p>Podpis HMAC SHA-256: timestamp + kropka + dokładna treść żądania. Nagłówki X-ServiceDesk-Timestamp i X-ServiceDesk-Signature.</p>'}`);return;
  }
}
function emailCodeForm(result){showModal(`<h2>${result.step==='old'?'Potwierdź obecny adres':'Potwierdź nowy adres'}</h2><p>${e(result.message)}</p><form data-extra="email-code" data-token="${e(result.token)}">${input('Kod z wiadomości','code','','required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code"')}${saveFooter('Potwierdź kod')}</form>`);}
document.addEventListener('submit',async event=>{const form=event.target.closest('[data-extra]');if(!form)return;event.preventDefault();if(form.dataset.busy)return;form.dataset.busy='1';const buttons=[...form.querySelectorAll('button[type="submit"]')];buttons.forEach(b=>b.disabled=true);try{await extraSubmit(form);}catch(err){const error=$('.form-error',form);if(error)error.textContent=err.message;else notify(err.message,true);}finally{delete form.dataset.busy;buttons.forEach(b=>b.disabled=false);}});

window.matchMedia?.('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if((S.user?.theme||'system')==='system')applyTheme();});
async function boot(){
  try{
    S.config=await api('/public-config');applyTheme();if(S.config.setup_required)return setupView();
    try{const session=await api('/me');S.user=session.user;S.csrf=session.csrf;}catch(err){if(!err.message.includes('Zaloguj się'))throw err;S.user=null;}
    if(S.user&&!S.user.must_change)await refreshMeta();await route();
  }catch(err){app.innerHTML=`<main id="main" class="empty"><h1>Nie udało się połączyć</h1><p>${e(err.message)}</p><button data-action="refresh">Spróbuj ponownie</button></main>`;}
}
