if(document.modelContext?.registerTool) {
  const lifecycle=new AbortController();
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
  try {
    Promise.resolve(document.modelContext.registerTool({name:'start_ticket_creation',description:'Otwórz formularz nowego zgłoszenia. Nie zapisuje ani nie wysyła zgłoszenia.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},async execute(input){if(!input || Object.keys(input).length)throw new Error('Niedozwolone parametry.');if(!S.user||!S.meta||S.user.must_change)throw new Error('Zaloguj się i zmień hasło tymczasowe.');await createTicketModal();return {form:'open',created:false};}}, {signal:lifecycle.signal})).catch(()=>{});
  }catch{}
}
