// 0.6: administration, installation and ticket lifecycle.
function v6button(action,label,attrs=''){return `<button type="button" data-v6-action="${e(action)}" ${attrs}>${e(label)}</button>`;}
function notificationBell(){return '<button type="button" class="notification-bell" data-v6-action="notifications" aria-label="Powiadomienia"><svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zM10 20h4"/></svg><span data-bell-count hidden></span></button>';}
async function refreshNotifications(){if(!isStaff()||S.user.must_change)return;try{const current=S.user.id,result=await api('/desk/notifications');if(S.user?.id!==current)return;S.notifications=result;if(modal.open&&$('[data-notification-list]',modal))$('[data-notification-list]',modal).innerHTML=notificationsMarkup();document.querySelectorAll('[data-bell-count]').forEach(el=>{el.hidden=result.unread===0;el.textContent=result.unread>99?'99+':result.unread;el.parentElement.setAttribute('aria-label',`Powiadomienia: ${result.unread} nieprzeczytanych`);});}catch{/* A transient polling failure must not interrupt an edited form. */}}
const bellInterval=setInterval(()=>{if(!document.hidden)void refreshNotifications();},5000);
window.addEventListener('pagehide',()=>clearInterval(bellInterval),{once:true});
function notificationsMarkup(){const n=S.notifications||{items:[],unread:0};return `<h2>Powiadomienia <span class="count">${n.unread}</span></h2><div class="button-row">${v6button('notifications-seen','Oznacz widoczne jako przeczytane',`data-through="${n.items[0]?.id||0}"`)}</div><div class="notification-list">${n.items.map(x=>`<a class="notification-item${x.seen?'':' unread'}" data-v6-action="notification-read" data-id="${x.id}" href="${x.ticket_key?'#/ticket/'+e(x.ticket_key):'#/admin/approvals'}"><span>${e(x.body)}</span><time>${date(x.created_at)}</time></a>`).join('')||'<p class="hint">Nie masz nowych powiadomień.</p>'}</div>`;}
function ticketToolsV6(t){return v6button('watch','👁 '+t.watcher_count+(t.watching?' · Obserwujesz':' · Obserwuj'),`aria-pressed="${Boolean(t.watching)}" title="${e((t.watchers||[]).map(u=>u.name+' (@'+u.username+')').join(', ')||'Nikt jeszcze nie obserwuje')}"`)+v6button('archive',t.archived_at?'Przywróć z archiwum':'Archiwizuj')+(S.user.role==='admin'?v6button('delete-ticket','Usuń zgłoszenie','class="danger-text"'):'');}
function updateKeyPreview(){const form=$('[data-form="create-project"], [data-form="project-general"]');if(!form)return;const output=$('[data-key-example]',form);if(!output)return;const key=form.elements.key.value.trim().toUpperCase()||'IT',padding=Math.max(0,Math.min(10,Number(form.elements.number_padding.value)||0)),number=Math.max(1,Number(form.elements.next_number.value)||1);output.textContent=key+'-'+String(number).padStart(padding,'0');}
async function fileBase64(file){if(!file||file.size>2*1024*1024)throw new Error('Wybierz obraz o rozmiarze do 2 MB.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Nie udało się odczytać pliku.'));reader.readAsDataURL(file);});}
function setupView(){
  document.title='Instalacja · Service Desk';app.innerHTML=`<main id="main" class="setup-layout"><section class="setup-intro"><img src="/favicon.svg" width="48" height="48" alt=""><div class="eyebrow">SERVICE DESK · ${e(S.config.version||'0.6.0')}</div><h1>Twoje centrum<br>obsługi zgłoszeń.</h1><p>Nadaj mu nazwę, dodaj logo i utwórz konto administratora. Projekty, zespoły oraz pocztę ustawisz po zalogowaniu.</p><div class="setup-step"><span>01</span><div><strong>Organizacja</strong><p>Marka widoczna w portalu i korespondencji.</p></div></div><div class="setup-step"><span>02</span><div><strong>Administrator</strong><p>Pierwsze konto zarządzające systemem.</p></div></div></section><section class="panel setup-form"><h2>Konfiguracja pierwszego uruchomienia</h2><form data-v6="setup">${input('Kod instalacji z logu kontenera','token','','required autocomplete="off" maxlength="200"')}${input('Nazwa organizacji','company_name','','required maxlength="100" placeholder="Nazwa Twojej organizacji"')}${input('Nazwa systemu','brand_name','Service Desk','required maxlength="80"')}<label>Logo organizacji · opcjonalnie<input type="file" name="logo" accept="image/png,image/jpeg,image/webp"></label><div class="form-row">${input('Imię administratora','first_name','','required autocomplete="given-name" maxlength="60"')}${input('Nazwisko','last_name','','autocomplete="family-name" maxlength="80"')}</div>${input('E-mail administratora','email','','required type="email" autocomplete="username"')}${input('Hasło','password','','required type="password" minlength="12" maxlength="256" autocomplete="new-password"')}${input('Powtórz hasło','repeat','','required type="password" minlength="12" maxlength="256" autocomplete="new-password"')}<p class="hint">Co najmniej 12 znaków. Rejestrację klientów włączysz w ustawieniach.</p>${saveFooter('Uruchom centrum wsparcia')}</form></section></main>`;
}
