async function legacySettingsView(){
  const [s,smtp,mail,system]=await Promise.all([api('/settings'),api('/desk/smtp'),api('/desk/outbox'),api('/desk/system')]);S.settings=s;S.smtp=smtp;
  return heading('ADMINISTRACJA','Ustawienia systemu',`<a class="button version-chip" href="#/admin/updates">Wersja ${e(system.version)}</a>`)+`<div class="settings-grid"><section class="panel detail-panel"><h2>Organizacja i rejestracja</h2><form data-form="settings" data-version="${s.version}">${input('Nazwa organizacji','company_name',s.company_name||s.brand_name,'required maxlength="100"')}${input('Nazwa systemu','brand_name',s.brand_name,'required maxlength="80"')}${pick('Rejestracja kont','registration_mode',registerNames,s.registration_mode)}<label>Dopuszczone domeny klientów<textarea name="allowed_domains" rows="3" placeholder="firma.example — po jednej domenie w wierszu">${e(s.allowed_domains.join('\n'))}</textarea></label><p class="hint">Pusta lista dopuszcza wszystkie domeny. Rejestracja tworzy konto klienta i nie nadaje roli pracownika.</p>${saveFooter()}</form><h3>Logo</h3><form data-v6="logo"><img class="brand-preview" src="${e(S.config.logo_url||'/favicon.svg')}" alt="Aktualne logo"><label>PNG, JPEG lub WebP · do 2 MB<input type="file" name="logo" accept="image/png,image/jpeg,image/webp" required></label>${saveFooter('Zapisz logo')}</form>${v6button('remove-logo','Przywróć logo domyślne')}</section><section class="panel detail-panel"><h2>Domyślna poczta SMTP</h2><p>Ten serwer wysyła aktualizacje zgłoszeń, powiadomienia i wiadomości dotyczące kont. Zespoły mogą używać własnych adresów nadawcy.</p><form data-v6="smtp" data-version="${smtp.version}">${check('Wysyłanie poczty aktywne','enabled',smtp.enabled)}${input('Serwer SMTP','host',smtp.host,'maxlength="253" placeholder="mail.example.com"')}<div class="form-row">${input('Port','port',smtp.port,'type="number" required min="1" max="65535"')}${pick('Szyfrowanie','secure',{starttls:'STARTTLS · zwykle port 587',tls:'TLS od połączenia · zwykle 465'},smtp.secure?'tls':'starttls')}</div>${input('Login SMTP (puste = bez uwierzytelnienia)','user',smtp.user,'autocomplete="off" maxlength="300"')}${input('Hasło SMTP','password','','type="password" autocomplete="new-password" placeholder="Puste = zachowaj zapisane hasło"')}${input('Domyślny adres nadawcy','from_email',smtp.from_email,'type="email" maxlength="254"')}${saveFooter('Zapisz SMTP')}</form>${v6button('smtp-test','Wyślij test na mój adres')}<p class="hint">Zapis działa od razu. Serwer SMTP musi zezwalać na wysyłanie z adresów skonfigurowanych dla zespołów.</p><a href="#/admin/mail">Skrzynki zespołów i odbiór IMAP →</a></section></div><section class="panel detail-panel"><h2>Kolejka poczty</h2><p class="hint">Oczekujące: ${system.mail_queued} · Nieudane: ${system.mail_failed}. Wiadomości pozostają w kolejce, gdy SMTP nie jest skonfigurowane.</p><div class="table-scroll"><table><thead><tr><th>Adresat i temat</th><th>Stan</th><th>Próby</th><th>Utworzono</th><th></th></tr></thead><tbody>${mail.map(m=>`<tr><td>${e(m.recipient)}<small class="row-meta">${e(m.subject)}</small></td><td>${e({queued:'W kolejce',sent:'Przyjęto przez SMTP',failed:'Błąd'}[m.status]||m.status)}<small class="row-meta">${e(m.last_error||'')}</small></td><td>${m.attempts}</td><td>${date(m.created_at)}</td><td>${m.status==='failed'?v6button('mail-retry','Ponów',`data-id="${m.id}"`):''}</td></tr>`).join('')||'<tr><td colspan="5">Brak wiadomości.</td></tr>'}</tbody></table></div></section><section class="panel detail-panel"><h2>Reset systemu</h2><p>Rozpocznij od nowa: usuń dane i konfigurację aplikacji. Wymagane hasło i kod e-mail.</p><button class="danger-text" data-v71-action="reset">Usuń wszystkie dane</button></section>`;
}
function workflowGraph(w,focus){
  const selected=w.statuses.find(s=>s.key===focus)||w.statuses.find(s=>s.key===w.initial)||w.statuses[0];
  const columns=3,nodeWidth=220,nodeHeight=60,dx=330,dy=150,positions=new Map(w.statuses.map((s,i)=>[s.key,{x:55+i%columns*dx,y:50+Math.floor(i/columns)*dy}]));
  const width=columns*dx+10,height=Math.max(220,Math.ceil(w.statuses.length/columns)*dy+50),edges=w.transitions.filter(t=>positions.has(t.from)&&positions.has(t.to));
  const graph=`<div class="workflow-canvas"><svg role="img" aria-label="Mapa statusów ze strzałkami przejść" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}"><defs><marker id="workflow-arrow" markerWidth="9" markerHeight="7" refX="8" refY="3.5" orient="auto"><path d="M0 0L9 3.5L0 7z"/></marker></defs>${edges.map((t,i)=>{const a=positions.get(t.from),b=positions.get(t.to),forward=b.x>a.x||b.y>a.y;const x1=a.x+nodeWidth/2,y1=a.y+(forward?nodeHeight:0),x2=b.x+nodeWidth/2,y2=b.y+(forward?0:nodeHeight),bend=45+(i%5)*12;return `<path class="workflow-edge${t.from===selected?.key?' active':''}" d="M${x1} ${y1} C${x1} ${y1+(forward?bend:-bend)} ${x2} ${y2+(forward?-bend:bend)} ${x2} ${y2}" marker-end="url(#workflow-arrow)"><title>${e((w.statuses.find(s=>s.key===t.from)?.name||t.from)+' → '+(w.statuses.find(s=>s.key===t.to)?.name||t.to)+': '+(t.name||''))}</title></path>`;}).join('')}${w.statuses.map(s=>{const p=positions.get(s.key);return `<g class="graph-status ${e(s.category)}${selected?.key===s.key?' focused':''}" data-action="focus-state" data-state="${e(s.key)}" role="button" tabindex="0" aria-label="${e(s.name)}"><rect x="${p.x}" y="${p.y}" width="${nodeWidth}" height="${nodeHeight}" rx="10"/><text x="${p.x+14}" y="${p.y+25}">${e((s.name||'Nowy status').slice(0,25))}</text><text class="graph-category" x="${p.x+14}" y="${p.y+45}">${e((s.key===w.initial?'Początek · ':'')+(S.meta.statuses[s.category]||''))}</text><title>${e(s.name)}</title></g>`;}).join('')}</svg></div>`;
  return graph+(selected?`<div class="workflow-focus"><strong>${e(selected.name||'Nowy status')}</strong><div>${edges.filter(t=>t.from===selected.key).map(t=>`<span class="transition-chip">${e(t.name||w.statuses.find(s=>s.key===t.to)?.name)} → ${e(w.statuses.find(s=>s.key===t.to)?.name)}<small>${e({team:'Zespół',customer:'Zgłaszający',both:'Zespół i zgłaszający'}[t.actor])}</small></span>`).join('')||'<span class="hint">Brak przejść wychodzących.</span>'}</div></div>`:'');
}
async function templateViewV6(id){
  if(!isStaff())return empty('Widok zespołu');const rows=await api('/desk/templates');S.extra={section:'templates',rows};
  if(!id)return heading('WSPÓLNA KONFIGURACJA','Szablony obiegów',S.user.role==='admin'?'<a class="button primary" href="#/admin/templates/new">Nowy szablon</a>':'')+`<p class="lead">Edytuj statusy i przejścia we wspólnym szablonie. Zmiany obejmą przypisane projekty; ich automatyzacje pozostaną oddzielne.</p><div class="template-grid">${rows.map(t=>`<section class="panel detail-panel"><div class="section-heading"><h2>${e(t.name)}</h2>${t.is_default?'<span class="pill resolved">Domyślny</span>':''}</div><p>${t.config.statuses.length} statusów · ${t.config.transitions.length} przejść</p><p class="hint">Projekty: ${t.projects.map(p=>e(p.key)).join(', ')||'nieużywany'}</p><div class="button-row"><a class="button" href="#/admin/templates/${t.id}">${S.user.role==='admin'?'Edytuj mapę':'Pokaż mapę'}</a>${extraButton('template-clone','Klonuj',`data-id="${t.id}"`)}${extraButton('template-apply','Zastosuj',`data-id="${t.id}"`)}${S.user.role==='admin'?v6button('template-delete','Usuń',`data-id="${t.id}" data-version="${t.version}"${t.projects.length?' disabled title="Szablon jest używany przez projekty"':''}`):''}</div></section>`).join('')}</div>`;
  const t=id==='new'?{name:'',version:0,is_default:false,projects:[],config:{initial:'open',statuses:[{key:'open',name:'Nowe',category:'open'},{key:'closed',name:'Zamknięte',category:'closed'}],transitions:[{from:'open',to:'closed',name:'Zamknij',actor:'team'}],rules:[]}}:rows.find(t=>t.id===Number(id));if(!t)return empty('Szablon nie istnieje');S.template=t;
  if(S.user.role!=='admin')return heading('MAPA OBIEGU',t.name)+workflowGraph(t.config,t.config.initial);
  const w=t.config,map=Object.fromEntries(w.statuses.map(s=>[s.key,s.name]));return heading('SZABLON OBIEGU',t.id?t.name:'Nowy szablon','<a class="button" href="#/admin/templates">Wszystkie szablony</a>')+`<form data-v6="template" data-id="${t.id||''}" data-version="${t.version}"><section class="panel detail-panel">${input('Nazwa szablonu','name',t.name,'required maxlength="100"')}${check('Domyślny dla nowych projektów','is_default',t.is_default)}<p class="hint">Zapis zmieni mapy projektów: ${t.projects.map(p=>e(p.key)).join(', ')||'brak przypisanych projektów'}. Nie można usunąć statusu używanego przez ich zgłoszenia lub reguły.</p><div id="workflow-graph">${workflowGraph(w,w.initial)}</div></section><section class="panel detail-panel"><div class="section-heading"><h2>Statusy</h2><button type="button" data-action="add-state">Dodaj status</button></div><div class="table-scroll"><table><thead><tr><th>Nazwa</th><th>Kategoria</th><th></th></tr></thead><tbody id="workflow-statuses">${w.statuses.map(workflowStatusRow).join('')}</tbody></table></div><label>Status początkowy<select name="initial" data-state-select>${options(map,w.initial)}</select></label></section><section class="panel detail-panel"><div class="section-heading"><h2>Przejścia</h2><button type="button" data-action="add-transition">Dodaj przejście</button></div><div class="table-scroll"><table><thead><tr><th>Ze statusu</th><th>Do statusu</th><th>Dostęp</th><th>Nazwa przejścia</th><th></th></tr></thead><tbody id="workflow-transitions">${w.transitions.map(x=>transitionRow(x,map)).join('')}</tbody></table></div></section><div class="editor-save">${saveFooter('Zapisz szablon i mapy projektów')}</div></form>`;
}
async function boardView(search){
  const active=S.meta.projects.filter(p=>p.can_work&&p.project_type!=='assets'&&!p.archived);
  if(!active.length)return empty('Utwórz projekt, aby rozpocząć pracę na tablicy');
  let p=active.find(p=>p.id===Number(search.get('project')))||active[0];search=new URLSearchParams(search);search.set('project',p.id);
  let html=await boardViewLegacy(search);html=html.replace('</div><form class="filters"',`</div>${p.can_manage?`<div class="button-row board-tools"><a class="button" href="#/project/${p.id}?tab=workflow">Statusy i mapa projektu</a></div>`:''}<form class="filters"`);
  return html.replace('Wszystkie projekty</option>','Wybierz projekt</option>');
}
async function boardTransition(key,state,version){const data=await api('/tickets/'+key);if(data.ticket.version!==version)throw new Error('Zgłoszenie zmieniło się. Odśwież tablicę.');S.ticket=data.ticket;return transitionWithResolution(state);}
async function apiTokensView(){
  if(S.user.role!=='admin')return empty('Tokeny konfiguruje administrator');const [rows,users]=await Promise.all([api('/desk/api-tokens'),api('/users')]);S.apiUsers=users;S.apiTokens=rows;
  return heading('INTEGRACJE','API i tokeny',v6button('api-create','Utwórz token'))+`<p class="lead">Jeden token działa jako wybrane konto w jednym projekcie. Hasła użytkowników i sesje WWW nie są używane do integracji.</p><section class="panel table-scroll"><table><thead><tr><th>Token</th><th>Projekt / konto</th><th>Uprawnienia</th><th>Ważność</th><th></th></tr></thead><tbody>${rows.map(t=>`<tr><td>${e(t.name)}</td><td>${e(t.project_key)} · ${e(t.user_name)}</td><td>${e(t.scopes.join(', '))}</td><td>${t.revoked_at?'Odwołany':date(t.expires_at)}</td><td>${!t.revoked_at?v6button('api-revoke','Odwołaj',`data-id="${t.id}"`):''}</td></tr>`).join('')||'<tr><td colspan="5">Brak tokenów.</td></tr>'}</tbody></table></section><section class="panel detail-panel"><h2>Użycie API</h2><p><code>Authorization: Bearer TOKEN</code> · format JSON</p><p><code>GET /api/v1/forms</code> — formularze projektu<br><code>GET /api/v1/tickets</code> — lista z parametrami after i limit<br><code>GET /api/v1/tickets/KLUCZ</code> — zgłoszenie i dozwolone przejścia<br><code>POST /api/v1/tickets</code> — utworzenie sprawy<br><code>POST /api/v1/tickets/KLUCZ/comments</code> — odpowiedź<br><code>POST /api/v1/tickets/KLUCZ/transitions</code> — zmiana statusu</p><p class="hint">Każdy POST wymaga nagłówka Idempotency-Key z unikalnym identyfikatorem żądania. Przykłady i pełne pola opisano w API.md.</p><a href="#/admin/webhooks">Webhooki przychodzące i automatyzacja →</a></section>`;
}

async function v6Action(action,button){
  const id=Number(button.dataset.id);
  if(action==='notifications'){await refreshNotifications();showModal('<div data-notification-list>'+notificationsMarkup()+'</div>');return;}
  if(action==='notification-read'){await api('/desk/notifications',{method:'POST',data:{id}});modal.close();location.hash=button.getAttribute('href');await refreshNotifications();return;}
  if(action==='notifications-seen'){S.notifications=await api('/desk/notifications',{method:'POST',data:{all:true,through_id:Number(button.dataset.through)}});showModal('<div data-notification-list>'+notificationsMarkup()+'</div>');await refreshNotifications();return;}
  if(action==='watch'){await api('/desk/tickets/'+S.ticket.id+'/watch',{method:'POST',data:{watching:!S.ticket.watching}});return route();}
  if(action==='archive'){showModal(`<h2>${S.ticket.archived_at?'Przywróć z archiwum':'Archiwizuj zgłoszenie'}</h2><p>${e(S.ticket.key)} · ${e(S.ticket.title)}</p><p>${S.ticket.archived_at?'Sprawa wróci do listy bieżących zgłoszeń. Zamknięcie pozostaje ostateczne.':'Zgłoszenie zachowa treść i numer. Nie będzie przyjmować zmian; znajdziesz je przez filtr archiwum.'}</p><form data-v6="archive">${saveFooter(S.ticket.archived_at?'Przywróć':'Archiwizuj')}</form>`);return;}
  if(action==='delete-ticket'){showModal(`<h2>Usuń zgłoszenie</h2><p>Treść sprawy i rozmowa zostaną usunięte. Klucz <strong>${e(S.ticket.key)}</strong> pozostanie zarezerwowany na stałe. Operacja nie usuwa osobnych spraw powiązanych.</p><form data-v6="delete-ticket">${input('Wpisz pełny klucz, aby potwierdzić','confirm_key','','required autocomplete="off"')}${saveFooter('Usuń trwale')}</form>`);return;}
  if(action==='unlink'){const l=S.ticket.links.find(l=>l.id===id);showModal(`<h2>Usuń powiązanie</h2><p>${e(S.ticket.key)} ↔ ${e(l.key)}</p><p>Obie sprawy pozostaną w systemie. Synchronizacja tej pary zostanie zatrzymana.</p><form data-v6="unlink" data-id="${id}">${saveFooter('Odłącz zgłoszenia')}</form>`);return;}
  if(action==='link-select'){const field=$('[data-link-search]',modal);field.value=button.dataset.key;field.setAttribute('aria-expanded','false');$('#link-options',modal).innerHTML='';field.focus();return;}
  if(action==='template-delete'){const t=S.extra.rows.find(t=>t.id===id);showModal(`<h2>Usuń nieużywany szablon</h2><p>${e(t.name)}. Serwer ponownie sprawdzi przypisania projektów przed usunięciem.</p><form data-v6="template-delete" data-id="${id}" data-version="${t.version}">${saveFooter('Usuń szablon')}</form>`);return;}
  if(action==='smtp-test'){button.disabled=true;try{notify((await api('/desk/smtp/test',{method:'POST',data:{}})).message);}finally{button.disabled=false;}return;}
  if(action==='mail-retry'){await api('/desk/outbox/'+id,{method:'POST',data:{}});notify('Wiadomość wróciła do kolejki.');return route();}
  if(action==='remove-logo'){await api('/desk/brand-logo',{method:'POST',data:{remove:true}});S.config=await api('/public-config');return route();}
  if(action==='board-status'){const p=S.meta.projects.find(p=>p.id===Number(button.dataset.project));showModal(`<h2>Dodaj status · ${e(p.name)}</h2><form data-v6="board-status" data-id="${p.id}">${input('Nazwa statusu','name','','required maxlength="80"')}${pick('Kategoria','category',S.meta.statuses,'in_progress')}${pick('Przejście do nowego statusu ze statusu','from',Object.fromEntries(p.workflow_statuses.filter(s=>s.category!=='closed').map(s=>[s.key,s.name])),null)}<p class="hint">Nowy status pojawi się od razu na tablicy. Dalsze przejścia ustawisz w mapie projektu. Edycja tworzy lokalną mapę tego projektu.</p>${saveFooter('Dodaj status i przejście')}</form>`);return;}
  if(action==='api-create'){showModal(`<h2>Token integracji</h2><form data-v6="api-token">${input('Nazwa','name','','required maxlength="100"')}${pick('Projekt','project_id',Object.fromEntries(S.meta.projects.filter(p=>p.can_manage&&p.project_type!=='assets'&&!p.archived).map(p=>[p.id,p.name])),null)}${pick('Konto automatyzacji','user_id',Object.fromEntries(S.apiUsers.filter(u=>u.active).map(u=>[u.id,u.name])),null)}${multi('Uprawnienia','scopes',{'tickets:read':'Odczyt zgłoszeń i formularzy','tickets:create':'Tworzenie zgłoszeń','tickets:comment':'Dodawanie odpowiedzi','tickets:transition':'Zmiana statusu','tickets:internal':'Odczyt i dodawanie notatek wewnętrznych'},['tickets:read'])}${input('Ważność w dniach','expires_in_days',90,'type="number" min="1" max="365" required')}${saveFooter('Utwórz token')}</form>`);return;}
  if(action==='api-revoke'){await api('/desk/api-tokens/'+id+'/revoke',{method:'POST',data:{}});return route();}
  if(action.startsWith('release-'))return releaseAction(action,button);
}
async function v6Submit(form){
  const fields=Object.fromEntries(new FormData(form)),kind=form.dataset.v6,id=Number(form.dataset.id);let result;
  if(kind==='setup'){if(fields.password!==fields.repeat)throw new Error('Hasła muszą być identyczne.');result=await api('/setup',{method:'POST',data:{...fields,logo:form.elements.logo.files[0]?await fileBase64(form.elements.logo.files[0]):undefined}});S.config=await api('/public-config');notify(result.message);location.hash='#/login';return route();}
  if(kind==='smtp'){await api('/desk/smtp',{method:'POST',data:{...fields,version:Number(form.dataset.version),enabled:fields.enabled==='on',port:Number(fields.port),secure:fields.secure==='tls'}});notify('Zapisano SMTP. Możesz wysłać test.');return route();}
  if(kind==='logo'){await api('/desk/brand-logo',{method:'POST',data:{data:await fileBase64(form.elements.logo.files[0])}});S.config=await api('/public-config');notify('Zapisano logo.');return route();}
  if(['archive','delete-ticket','unlink'].includes(kind)){const t=S.ticket;await api('/desk/tickets/'+t.id+'/'+(kind==='delete-ticket'?'delete':kind),{method:'POST',data:{version:t.version,archived:!t.archived_at,confirm_key:fields.confirm_key,link_id:id}});modal.close();notify('Zapisano zmianę.');if(kind==='delete-ticket')location.hash='#/queue';else await route();return;}
  if(kind==='template'){const w=readWorkflow();await api('/desk/templates'+(id?'/'+id:''),{method:id?'PATCH':'POST',data:{name:fields.name,version:Number(form.dataset.version),is_default:fields.is_default==='on',config:{...w,rules:[]}}});await refreshMeta();notify('Szablon i przypisane mapy zostały zapisane.');location.hash='#/admin/templates';return;}
  if(kind==='template-delete'){await api('/desk/templates/'+id+'/delete',{method:'POST',data:{version:Number(form.dataset.version)}});modal.close();notify('Usunięto szablon.');return route();}
  if(kind==='board-status'){const w=await api('/projects/'+id+'/workflow'),key=freshKey('status');w.statuses.push({key,name:fields.name,category:fields.category});w.transitions.push({from:fields.from,to:key,actor:'team',name:fields.name});await api('/projects/'+id+'/workflow',{method:'PATCH',data:w});modal.close();await refreshMeta();notify('Dodano status.');return route();}
  if(kind==='api-token'){result=await api('/desk/api-tokens',{method:'POST',data:{...fields,project_id:Number(fields.project_id),user_id:Number(fields.user_id),expires_in_days:Number(fields.expires_in_days),scopes:selected(form,'scopes')}});await route();showModal(`<h2>Zapisz token</h2><p>Ten token zostanie pokazany tylko teraz. Przechowuj go jako sekret integracji.</p><textarea readonly rows="4">${e(result.generated_secret)}</textarea><p>Ważny do ${date(result.expires_at)}.</p>`);return;}
  if(kind==='release-confirm')return installRelease(form);
  if(kind==='release-settings')return saveReleaseSettings(form,fields);
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-v6-action]');if(!button||button.disabled)return;event.preventDefault();void v6Action(button.dataset.v6Action,button).catch(err=>notify(err.message,true));});
document.addEventListener('submit',async event=>{const form=event.target.closest('[data-v6]');if(!form)return;event.preventDefault();if(form.dataset.busy)return;form.dataset.busy='1';const buttons=[...form.querySelectorAll('button[type="submit"]')];buttons.forEach(b=>b.disabled=true);const error=$('.form-error',form);if(error)error.textContent='';try{await v6Submit(form);}catch(err){if(error)error.textContent=err.message;else notify(err.message,true);}finally{delete form.dataset.busy;buttons.forEach(b=>b.disabled=false);}});
let linkLookupTimer,linkLookupGeneration=0;
document.addEventListener('input',event=>{
  const field=event.target;if(['key','number_padding','next_number'].includes(field.name))updateKeyPreview();
  if(field.closest('[data-v6="template"]'))updateWorkflowPreview(field.name==='state_name');
  if(!field.matches('[data-link-search]'))return;clearTimeout(linkLookupTimer);const generation=++linkLookupGeneration,q=field.value.trim();$('#link-options',modal).innerHTML='';field.setAttribute('aria-expanded','false');if(!/^[a-z][a-z0-9]{1,9}-\d{3,10}$/i.test(q))return;
  linkLookupTimer=setTimeout(async()=>{try{const rows=await api('/desk/lookup?q='+encodeURIComponent(q)+'&exclude='+S.ticket.id);if(!field.isConnected||generation!==linkLookupGeneration)return;$('#link-options',modal).innerHTML=rows.map(r=>`<button type="button" role="option" aria-selected="false" data-v6-action="link-select" data-key="${e(r.key)}"><strong>${e(r.key)}</strong><span>${e(r.title)}</span>${r.archived?'<small>Archiwum</small>':''}</button>`).join('')||'<p class="hint">Brak dostępnych dopasowań.</p>';field.setAttribute('aria-expanded','true');}catch(err){if(field.isConnected&&generation===linkLookupGeneration)notify(err.message,true);}},250);
});
document.addEventListener('keydown',event=>{if(event.key==='ArrowDown'&&event.target.matches('[data-link-search]')){event.preventDefault();$('#link-options button',modal)?.focus();}if(event.target.closest('#link-options')&&['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();(event.key==='ArrowDown'?event.target.nextElementSibling:event.target.previousElementSibling)?.focus();}if(event.target.matches('.graph-status')&&['Enter',' '].includes(event.key)){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('change',event=>{if(event.target.closest('[data-v6="template"]'))updateWorkflowPreview();if(['smtp_mode','imap_enabled'].includes(event.target.name))updateMailMode(event.target.closest('form'));});
function updateMailMode(form){const imap=$('[data-imap-config]',form);if(imap){imap.hidden=!form.elements.imap_enabled.checked;imap.disabled=!form.elements.imap_enabled.checked;}const fieldset=$('[data-smtp-custom]',form);if(fieldset){const custom=form.elements.smtp_mode.value==='custom';fieldset.hidden=!custom;fieldset.disabled=!custom;}}
function mailEditorV6(r,c,pmap){return `${input('Nazwa zespołu','name',r.name,'required')}${pick('Projekt zgłoszeń','project_id',pmap,r.project_id)}${input('Adres skrzynki / nadawcy','email',r.email,'required type="email" placeholder="support@example.com"')}<p class="hint">Odpowiedzi klientów trafiają do tej skrzynki IMAP. Wysyłanie używa wyłącznie SMTP tej skrzynki. Wyłączenie jej nie przełącza wysyłki na główne SMTP.</p>${check('Odbieraj zgłoszenia przez IMAP','imap_enabled',c.imap_enabled??true)}<fieldset data-imap-config><legend>Odbiór IMAP</legend>${input('Serwer IMAP','imap_host',c.imap_host,'required')}${input('Port','imap_port',c.imap_port||993,'type="number" min="1" max="65535" required')}${check('TLS od połączenia · port 993','imap_secure',c.imap_secure??true)}${input('Login IMAP','imap_user',c.imap_user,'required autocomplete="off"')}${input('Hasło IMAP','imap_pass','','type="password" autocomplete="new-password" placeholder="Puste = zachowaj zapisane hasło"')}${input('Folder','folder',c.folder||'INBOX','required')}</fieldset><input type="hidden" name="smtp_mode" value="custom"><fieldset data-smtp-custom><legend>Osobny SMTP tego zespołu</legend>${input('Serwer SMTP','smtp_host',c.smtp_host,'required')}${input('Port SMTP','smtp_port',c.smtp_port||587,'type="number" required min="1" max="65535"')}${check('TLS od połączenia · port 465','smtp_secure',c.smtp_secure)}${input('Login SMTP','smtp_user',c.smtp_user,'autocomplete="off"')}${input('Hasło SMTP','smtp_pass','','type="password" autocomplete="new-password" placeholder="Puste = zachowaj zapisane hasło"')}</fieldset><label>Formularz nowych zgłoszeń<select name="request_type_id" required></select></label>${check('Zaproś nieznanych nadawców jako klientów','allow_new_senders',c.allow_new_senders)}${input('Dopuszczone domeny nowych nadawców','allowed_domains',(c.allowed_domains||[]).join(', '))}${check('Przy pierwszym odczycie pobieraj tylko nowe wiadomości','start_from_now',c.start_from_now??true)}${check('Skrzynka aktywna','enabled',r.enabled)}`;}
async function updatesView(){const s=await api('/desk/updates');S.release=s;return heading('ADMINISTRACJA','Wersja i aktualizacje',`<span class="version-chip">${e(s.current_version)}</span>`)+`<p>Nowe wydania są sprawdzane automatycznie co 6 godzin. Możesz też sprawdzić je teraz.</p><section class="panel detail-panel"><h2>Dostępne wydanie</h2><p>Zainstalowana wersja: <strong>${e(s.current_version)}</strong> · Schemat bazy: ${s.schema}</p><p>Ostatnie sprawdzenie: ${s.checked_at?date(s.checked_at):'jeszcze nie sprawdzano'}</p>${s.last_error?`<p class="form-error">${e(s.last_error)}</p>`:''}${s.latest?`<p>Najnowsza wersja: <strong>${e(s.latest.version)}</strong> · ${s.update_available?'Dostępna aktualizacja':'Masz aktualną lub nowszą wersję'}</p><a href="${e(s.latest.url)}" target="_blank" rel="noopener noreferrer">Informacje o wydaniu ↗</a><pre class="release-notes">${e(s.latest.notes||'Brak opisu wydania.')}</pre>`:''}<div class="button-row">${v6button('release-check','Sprawdź teraz')}${s.update_available?v6button('release-install','Zainstaluj '+s.latest.version,s.agent_available?'class="primary"':'disabled'):''}</div><p class="hint">Aktualizator: ${s.agent_available?'połączony':'nieuruchomiony — administrator serwera musi włączyć profil updates'}. Instalacja wymaga krótkiej przerwy. Kopia danych powstaje przed migracją.</p><div id="release-job">${releaseJob(s.job)}</div></section>`;}
function releaseJob(job){return job?`<div class="release-job" role="status"><strong>${e({queued:'W kolejce',pulling:'Pobieranie',backing_up:'Kopia danych',starting:'Uruchamianie',checking:'Kontrola',committed:'Zatwierdzono',done:'Gotowe',failed:'Przerwano',rollback:'Przywracanie',rolled_back:'Przywrócono',rollback_failed:'Wymagana interwencja'}[job.phase]||job.phase)}</strong><p>${e(job.message)}</p>${job.backup?`<p class="hint">Kopia: ${e(job.backup)}</p>`:''}<small>${date(job.at)}</small></div>`:'';}
async function saveReleaseSettings(form,b){await api('/desk/updates',{method:'POST',data:{version:Number(form.dataset.version),repository:b.repository,token:b.token,clear_token:form.elements.clear_token.checked,automatic_checks:true}});notify('Zapisano źródło wydań.');await route();}
async function releaseAction(action){if(action==='release-check'){notify('Sprawdzam GitHub…');await api('/desk/updates/check',{method:'POST',data:{}});await route();return;}if(action==='release-install'){showModal(`<h2>Zainstaluj wersję ${e(S.release.latest.version)}</h2><p>System zapisze kopię danych, zatrzyma obsługę zgłoszeń i uruchomi nowe wydanie. Podczas aktualizacji nie zamykaj tej karty.</p><form data-v6="release-confirm">${saveFooter('Rozpocznij aktualizację')}</form>`);}}
async function installRelease(form){const button=form.querySelector('button[type="submit"]');button.disabled=true;try{await api('/desk/updates/install',{method:'POST',data:{version:S.release.latest.version}});modal.close();notify('Zlecono aktualizację.');let attempts=0;const timer=setInterval(async()=>{if(++attempts>600||!location.hash.includes('/admin/updates')){clearInterval(timer);return;}try{const r=await fetch('/api/desk/updates',{credentials:'same-origin'});if(!r.ok)return;const s=await r.json();const panel=$('#release-job');if(panel)panel.innerHTML=releaseJob(s.job);if(['done','rolled_back','failed','rollback_failed'].includes(s.job?.phase)){clearInterval(timer);notify(s.job.message,s.job.phase!=='done');}}catch{}},2000);}catch(err){notify(err.message,true);button.disabled=false;}}

// 0.7: central workflows, MFA, mail templates and automatic update notices.
function mappingRow(m={}){return `<div class="mapping-row">${input('DN grupy','group_dn',m.group_dn||'','required maxlength="4096"')}${pick('Projekt','project_id',projectMap(),m.project_id)}${pick('Rola w projekcie','mapping_role',memberNames,m.role||'requester')}<button type="button" data-action="remove-mapping">Usuń</button></div>`;}
