function mfaLoginView(){authCard('Weryfikacja dwuetapowa',`<p>Wpisz kod z aplikacji uwierzytelniającej, kod odzyskiwania albo użyj zarejestrowanego klucza sprzętowego.</p><form data-v7="mfa-login">${input('Kod','code','','required autocomplete="one-time-code" maxlength="40" autofocus')}${saveFooter('Potwierdź logowanie')}</form><button type="button" class="button full" data-security-action="key-login" data-challenge="${e(S.mfaChallenge||'')}">Użyj klucza sprzętowego</button><a href="#/login">Wróć do logowania</a>`);}
async function mfaDialog(){const s=await api('/mfa/status');showModal(`<h2>Weryfikacja dwuetapowa</h2><p>${s.enabled?'Aktywna. Pozostałe kody odzyskiwania: '+s.recovery_remaining:'Zabezpiecz konto kodem z aplikacji uwierzytelniającej.'}</p>${s.enabled?`<form data-v7="mfa-disable">${input('Kod 2FA lub kod odzyskiwania','code','','required autocomplete="one-time-code"')}${saveFooter('Wyłącz 2FA')}</form>`:'<button class="primary" data-v7-action="mfa-setup">Skonfiguruj 2FA</button>'}`);}
async function mailTemplatesView(){const rows=await api('/desk/mail-templates');S.mailTemplates=rows;return heading('POCZTA','Szablony i wyzwalacze e-mail','<button data-v7-action="mail-new" class="primary">Dodaj szablon</button>')+`<p>Szablon dla „Uczestników zgłoszenia” zastępuje standardową wiadomość danego zdarzenia. Pozostałe szablony wysyłają dodatkowe powiadomienia. Akcja automatyzacji może użyć szablonu z wyzwalaczem „Tylko automatyzacja”.</p><div class="template-grid">${rows.map(t=>`<section class="panel detail-panel"><h2>${e(t.name)}</h2><p>${e(mailEventNames[t.event])} · ${e(mailAudienceNames[t.audience])}</p><p>${e(S.meta.projects.find(p=>p.id===t.project_id)?.name||'Wszystkie projekty')} · ${t.enabled?'Aktywny':'Wyłączony'}</p><div class="button-row"><button data-v7-action="mail-edit" data-id="${t.id}">Edytuj</button><button data-v7-action="mail-delete" data-id="${t.id}">Usuń</button></div></section>`).join('')}</div>`;}
const mailEventNames={ticket_created:'Nowe zgłoszenie',status_changed:'Zmiana statusu',comment_added:'Dodanie komentarza',ticket_updated:'Edycja zgłoszenia',manual:'Tylko automatyzacja'};
const mailAudienceNames={participants:'Uczestnicy zgłoszenia',reporter:'Zgłaszający',watchers:'Obserwatorzy',team:'Zespół projektu',managers:'Kierownicy projektu'};
function mailTemplateDialog(t={}){showModal(`<h2>${t.id?'Edytuj':'Nowy'} szablon e-mail</h2><form data-v7="mail-template" data-id="${t.id||''}" data-version="${t.version||0}">${input('Nazwa','name',t.name,'required')}${pick('Projekt','project_id',projectMap(),t.project_id,'Wszystkie projekty')}${pick('Wyzwalacz','event',mailEventNames,t.event||'manual')}${pick('Odbiorcy','audience',mailAudienceNames,t.audience||'participants')}${input('Temat','subject',t.subject||'[{{key}}] {{title}}','required maxlength="200"')}<label>Treść<textarea name="body" rows="9" required maxlength="20000">${e(t.body||'Dzień dobry,\n\n{{update}}\n\nZgłoszenie: {{key}}\n{{url}}')}</textarea></label><p class="hint">Zmienne: {{key}}, {{title}}, {{description}}, {{update}}, {{status}}, {{url}}, {{reporter}}, {{project}}. System sam dodaje linię odpowiedzi i formatuje wiadomość HTML.</p>${check('Aktywny','enabled',t.enabled??true)}${saveFooter('Zapisz szablon')}</form>`);}
async function knowledgeView(){const c=await api('/desk/knowledge');return heading('INTEGRACJE','Baza wiedzy')+`<section class="panel detail-panel"><p>Przygotowanie połączenia z osobną aplikacją bazy wiedzy. Ta wersja zapisuje adres i kontrakt integracji; nie pobiera jeszcze artykułów.</p><form data-v7="knowledge" data-version="${c.version}">${input('Adres zewnętrznej bazy wiedzy','base_url',c.base_url||'','type="url" placeholder="https://knowledge.example.com"')}${check('Zapisz integrację jako aktywną','enabled',c.enabled??false)}${saveFooter('Zapisz')}</form></section>`;}
let statusDragging=null;
document.addEventListener('dragstart',ev=>{const row=ev.target.closest('.workflow-status-row');if(!row)return;if(!row.closest('[data-v6="template"]')||!ev.target.closest('.status-drag-handle')){ev.preventDefault();return;}statusDragging=row;ev.dataTransfer.effectAllowed='move';ev.dataTransfer.setData('text/plain',row.dataset.stateKey);});
document.addEventListener('dragover',ev=>{if(statusDragging&&ev.target.closest('#workflow-statuses'))ev.preventDefault();});
document.addEventListener('drop',ev=>{if(!statusDragging)return;const row=ev.target.closest('.workflow-status-row');if(row&&row!==statusDragging){ev.preventDefault();const rect=row.getBoundingClientRect();row.parentNode.insertBefore(statusDragging,ev.clientY<rect.y+rect.height/2?row:row.nextSibling);updateWorkflowPreview();}statusDragging=null;});
document.addEventListener('dragend',()=>{statusDragging=null;});
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-v7-action]');if(!b||b.disabled)return;try{
  const a=b.dataset.v7Action,id=Number(b.dataset.id);
  if(a==='mfa')return await mfaDialog();
  if(a==='mfa-setup'){const s=await api('/mfa/setup',{method:'POST',data:{}});showModal(`<h2>Dodaj konto w aplikacji uwierzytelniającej</h2><p>Wybierz ręczne wpisanie klucza: TOTP, 6 cyfr, okres 30 sekund.</p><code class="mfa-secret">${e(s.secret)}</code><p>Nazwa konta: ${e(S.user.email)}</p><form data-v7="mfa-enable">${input('Kod z aplikacji','code','','required inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}"')}${saveFooter('Włącz 2FA')}</form>`);return;}
  if(a==='mail-new')return mailTemplateDialog();
  if(a==='mail-edit')return mailTemplateDialog(S.mailTemplates.find(t=>t.id===id));
  if(a==='mail-delete'){const t=S.mailTemplates.find(t=>t.id===id);if(!confirm('Usunąć szablon '+t.name+'?'))return;await api('/desk/mail-templates/'+id+'/delete',{method:'POST',data:{version:t.version}});return route();}
  if(a==='state-up'||a==='state-down'){const row=b.closest('.workflow-status-row'),target=a==='state-up'?row.previousElementSibling:row.nextElementSibling;if(target)row.parentNode.insertBefore(row,a==='state-up'?target:target.nextSibling);updateWorkflowPreview();}
}catch(err){notify(err.message,true);}});
document.addEventListener('submit',async ev=>{const f=ev.target;if(!f.dataset.v7)return;ev.preventDefault();const b=Object.fromEntries(new FormData(f)),button=$('button[type="submit"]',f);if(button?.disabled)return;if(button)button.disabled=true;try{
  const kind=f.dataset.v7;
  if(kind==='mfa-login'){const r=await api('/mfa/verify',{method:'POST',data:{challenge:S.mfaChallenge,code:b.code}});S.user=r.user;S.csrf=r.csrf;S.mfaChallenge=null;if(!S.user.must_change)await refreshMeta();location.hash=isStaff()?'#/queue':'#/portal';return route();}
  if(kind==='mfa-enable'){const r=await api('/mfa/enable',{method:'POST',data:{code:b.code}});showModal(`<h2>2FA jest aktywne</h2><p>Zapisz kody odzyskiwania w bezpiecznym miejscu. Każdy można wykorzystać raz. Są widoczne tylko teraz.</p><pre>${e(r.recovery_codes.join('\n'))}</pre>`);return;}
  if(kind==='mfa-disable'){await api('/mfa/disable',{method:'POST',data:{code:b.code}});return mfaDialog();}
  if(kind==='mail-template'){await api('/desk/mail-templates'+(f.dataset.id?'/'+f.dataset.id:''),{method:f.dataset.id?'PATCH':'POST',data:{...b,project_id:b.project_id?Number(b.project_id):null,enabled:b.enabled==='on',version:Number(f.dataset.version)}});modal.close();return route();}
  if(kind==='knowledge'){await api('/desk/knowledge',{method:'POST',data:{...b,enabled:b.enabled==='on',version:Number(f.dataset.version)}});notify('Zapisano konfigurację integracji.');return route();}
}catch(err){notify(err.message,true);}finally{if(button)button.disabled=false;}});
let updateNoticeBusy=false;
async function updateNotice(){if(!S.user||S.user.role!=='admin'||document.hidden||updateNoticeBusy)return;updateNoticeBusy=true;try{const u=S.user.id,s=await api('/desk/updates');if(S.user?.id!==u)return;let el=$('#update-notice');if(!el){el=document.createElement('aside');el.id='update-notice';el.setAttribute('aria-live','polite');app.append(el);}el.hidden=!s.update_available;el.innerHTML=s.update_available?`Dostępna wersja <strong>${e(s.latest.version)}</strong> <a href="#/admin/updates">Zobacz aktualizację →</a>`:'';}catch{}finally{updateNoticeBusy=false;}}
setInterval(()=>void updateNotice(),15000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden){void refreshNotifications();void updateNotice();}});
window.addEventListener('focus',()=>{void refreshNotifications();void updateNotice();});

// 0.7.1: administrator account operations and explicit two-step system reset.
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-v71-action]');if(!b)return;try{
 if(b.dataset.v71Action==='toggle-user'){await api('/users/'+b.dataset.id,{method:'PATCH',data:{version:Number(b.dataset.version),active:b.dataset.active!=='true'}});await route();return;}
 if(b.dataset.v71Action==='asset-settings'){modal.close();location.hash=b.getAttribute('href');return;}
 if(b.dataset.v71Action==='delete-user'){if(!confirm('Usunąć konto? Dostęp zostanie odebrany, a dane profilu zanonimizowane. Historia zgłoszeń pozostanie.'))return;await api('/users/'+b.dataset.id+'/delete',{method:'POST',data:{version:Number(b.dataset.version)}});modal.close();await route();}
 if(b.dataset.v71Action==='reset'){showModal(`<h2>Usuń dane systemu</h2><p>Usuniesz wszystkie zgłoszenia, projekty, konta, zdjęcia i konfigurację aplikacji. System wróci do instalatora. Kopie zapasowe serwera pozostaną.</p><p>Wymagane jest hasło lokalnego administratora i kod wysłany na jego obecny e-mail.</p><form data-v71="reset-begin">${input('Hasło administratora','password','','required type="password" autocomplete="current-password"')}${saveFooter('Wyślij kod potwierdzający')}</form>`);}
}catch(err){notify(err.message,true);}});
document.addEventListener('submit',async ev=>{const f=ev.target;if(!f.dataset.v71)return;ev.preventDefault();const button=f.querySelector('[type=submit]');if(button.disabled)return;button.disabled=true;try{const b=Object.fromEntries(new FormData(f));
 if(f.dataset.v71==='user-avatar'){const file=f.elements.avatar.files[0];if(!file||file.size>2*1024*1024)throw new Error('Zdjęcie może mieć maksymalnie 2 MB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});await api('/users/'+f.dataset.id+'/avatar',{method:'POST',data:{version:Number(f.dataset.version),data}});modal.close();await route();}
 if(f.dataset.v71==='reset-begin'){await api('/system/reset',{method:'POST',data:{password:b.password}});showModal(`<h2>Potwierdź usunięcie wszystkich danych</h2><p>Kod wysłano na Twój e-mail. Jest ważny przez 10 minut. Po resecie kod nowej instalacji znajdziesz w logach kontenera.</p><form data-v71="reset-confirm">${input('Kod z e-maila','code','','required pattern="[0-9]{6}" autocomplete="one-time-code"')}${input('Hasło administratora','password','','required type="password" autocomplete="current-password"')}${input('Wpisz USUŃ WSZYSTKO','confirmation','','required')}${saveFooter('Nieodwracalnie usuń dane')}</form>`);}
 if(f.dataset.v71==='reset-confirm'){await api('/system/reset',{method:'POST',data:b});modal.close();S.user=null;app.innerHTML='<main class="panel detail-panel"><h1>Reset zatwierdzony</h1><p>Aplikacja uruchamia się ponownie. Odśwież stronę za kilka sekund. Kod instalacji odczytaj z logów kontenera.</p></main>';}
}catch(err){notify(err.message,true);}finally{button.disabled=false;}});

let liveViewBusy=false,liveQueueSignature='';
async function refreshLiveView(){
 if(!S.user||S.user.must_change||document.hidden||modal.open||liveViewBusy)return;
 const hash=location.hash,routeId=S.routeId;
 if(!/^#\/(ticket|queue|board)(\/|\?|$)/.test(hash))return;
 liveViewBusy=true;
 try{
  const draft=[...document.querySelectorAll('#main input:not([type=hidden]),#main textarea')].some(el=>el.value!==el.defaultValue);
  if(hash.startsWith('#/ticket/')){
   const before=S.ticket;if(!before)return;const data=await api('/tickets/'+encodeURIComponent(before.key));
   if(location.hash!==hash||S.routeId!==routeId||modal.open||data.ticket.version===before.version)return;
   if(draft||document.activeElement?.closest('#main form')){
    // Refresh the conversation without replacing a message being typed or its form.
    const temp=document.createElement('div');temp.innerHTML=(await detailViewV5(before.key,-1));
    if(location.hash!==hash||S.routeId!==routeId)return;
    const current=$('.conversation'),next=$('.conversation',temp);if(current&&next)current.replaceWith(next);
   }else{const y=window.scrollY;await route();window.scrollTo(0,y);}
  }else if(!draft&&!document.activeElement?.closest('#main form')){
   const query=hash.split('?')[1]||'',data=await api('/tickets?'+query),signature=JSON.stringify(data);
   if(location.hash!==hash||S.routeId!==routeId||modal.open)return;
   if(liveQueueSignature&&liveQueueSignature!==hash+signature){const y=window.scrollY;await route();window.scrollTo(0,y);}liveQueueSignature=hash+signature;
  }
 }catch{}finally{liveViewBusy=false;}
}
setInterval(()=>void refreshLiveView(),5000);
window.addEventListener('focus',()=>void refreshLiveView());
